 new.design_reference:=jsonb_build_object('mockupId',m.id,'title',m.title,'canonicalDraft',m.canonical_draft,'sha256',m.sha256,'planRevisionId',r.id,'planSha256',r.sha256,'approvedPages',r.content->'pages');
