create function public.social_schedule_item_guard(p_project uuid,v jsonb) returns public.social_content_revisions language plpgsql security invoker set search_path='' as $fn$
declare r public.social_content_revisions;reasons text[];
begin
 perform public.social_schedule_fields(v,array['postId','revisionId','sha256','decisionId','planRevisionId','bindingId','accountId','channel','asset','localMinute','scheduledAt','expiresAt','occasionId','kind','releaseCondition']);
 perform public.social_schedule_fields(v->'asset',array['id','sha256']);
 select c.* into r from public.social_content_posts p join public.social_content_revisions c on c.id=p.current_revision_id and c.post_id=p.id and c.project_id=p.project_id
 where p.project_id=p_project and p.id=(v->>'postId')::uuid and c.id=(v->>'revisionId')::uuid and c.sha256=v->>'sha256';
 if r.id is null or r.plan_revision_id is distinct from (v->>'planRevisionId')::uuid or r.binding_id is distinct from (v->>'bindingId')::uuid
 or r.binding->>'accountId' is distinct from v->>'accountId' or r.draft->>'channel' is distinct from v->>'channel'
 or r.draft->>'scheduledAt' is distinct from v->>'scheduledAt'
 or not exists(select 1 from public.social_content_decisions d where d.id=(v->>'decisionId')::uuid and d.project_id=p_project and d.post_id=r.post_id and d.revision_id=r.id and d.sha256=r.sha256 and d.decision='approve')
 then raise exception 'SOCIAL_SCHEDULE_REVIEW_REQUIRED';end if;
 reasons=array_remove(array_remove(public.social_content_requirements(r.id),'activation_required'),'time_passed');
 if array_length(reasons,1) is not null then raise exception 'SOCIAL_SCHEDULE_REVIEW_REQUIRED';end if;
 if r.draft->>'format'<>'image' or r.draft->>'channel' not in ('facebook','instagram') or r.draft->>'channel'='instagram' and char_length(r.draft->>'text')>2200
 or jsonb_array_length(r.media)<>1 or jsonb_array_length(r.draft->'mediaIds')<>1
 or r.media->0->>'id' is distinct from v->'asset'->>'id' or r.media->0->>'sha256' is distinct from v->'asset'->>'sha256'
 or r.media->0->>'mimeType'<>'image/jpeg' or r.draft->'mediaIds'->>0 is distinct from v->'asset'->>'id'
 or r.draft->>'linkUrl' is not null and position(r.draft->>'linkUrl' in r.draft->>'text')=0
 or not exists(select 1 from public.assets a where a.project_id=p_project and a.id=(v->'asset'->>'id')::uuid and a.status='active' and a.kind='image' and a.mime_type='image/jpeg' and a.checksum_sha256=v->'asset'->>'sha256' and a.byte_size between 1 and 8388608 and (a.width is null or a.width between 320 and 1440) and (a.height is null or a.height>0) and (a.width is null or a.height is null or a.width::numeric/nullif(a.height,0) between 0.8 and 1.91))
 then raise exception 'SOCIAL_SCHEDULE_REVIEW_REQUIRED';end if;
 return r;
end $fn$;
create function public.social_schedule_validate_manifest(p_project uuid,v jsonb) returns void language plpgsql security invoker set search_path='' as $fn$
declare item jsonb;t timestamptz;expiry timestamptz;condition jsonb;
begin
 perform public.social_schedule_fields(v,array['projectId','items']);
 if v->>'projectId' is distinct from p_project::text or jsonb_typeof(v->'items') is distinct from 'array' or jsonb_array_length(v->'items') not between 1 and 6 then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
 for item in select value from jsonb_array_elements(v->'items') loop
  perform public.social_schedule_item_guard(p_project,item);
  t=public.social_schedule_resolve_minute(item->>'localMinute');expiry=(item->>'expiresAt')::timestamptz;
  if t<=public.social_schedule_now() or t>public.social_schedule_now()+interval '366 days'
  or item->>'scheduledAt' is distinct from to_char(t at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"') or expiry<>t+interval '10 minutes'
  or coalesce(item->>'accountId','') !~ '^[0-9]{1,80}$' or coalesce(item->>'kind','') not in ('ordinary','month_release')
  or coalesce(item->>'occasionId','') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[1-8][a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$'
  then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
  condition=item->'releaseCondition';
  if item->>'kind'='ordinary' then if condition is distinct from 'null'::jsonb then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
  else
   perform public.social_schedule_fields(condition,array['releaseMonth','catalogSha256']);
   if coalesce(condition->>'releaseMonth','') !~ '^20[0-9]{2}-(0[1-9]|1[0-2])$' or coalesce(condition->>'catalogSha256','') !~ '^[a-f0-9]{64}$'
   or item->>'localMinute' is distinct from (condition->>'releaseMonth')||'-01T20:30' then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
  end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(v->'items') a group by a->>'postId' having count(*)>1)
 or exists(select 1 from jsonb_array_elements(v->'items') a group by a->>'occasionId',a->>'channel' having count(*)>1)
 or exists(select 1 from jsonb_array_elements(v->'items') a group by a->>'occasionId' having count(*)>2 or count(distinct a->>'scheduledAt')>1 or count(distinct a->>'kind')>1 or count(distinct (a->'releaseCondition')::text)>1)
 or exists(select 1 from jsonb_array_elements(v->'items') a group by date_trunc('week',(a->>'scheduledAt')::timestamptz at time zone 'Europe/Stockholm') having count(distinct a->>'occasionId')>3)
 then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
end $fn$;
create function public.social_schedule_revision(r public.social_content_revisions) returns jsonb language sql immutable security invoker set search_path='' as $fn$
 select jsonb_build_object('id',r.id,'sequence',r.sequence,'sha256',r.sha256,'planRevisionId',r.plan_revision_id,'draft',r.draft,'media',r.media,'binding',r.binding,'createdAt',r.created_at);
$fn$;
create function public.social_schedule_snapshot(j public.social_schedule_jobs) returns jsonb language sql stable security invoker set search_path='' as $fn$
 select jsonb_build_object('projectId',j.project_id,'manifestSha256',b.sha256,'approvalId',j.approval_id,'item',j.item,'revision',public.social_schedule_revision(c),'publication',case when p.id is null then null else public.social_publication_record(p) end)
 from public.social_schedule_batches b join public.social_content_revisions c on c.id=j.revision_id and c.post_id=j.post_id and c.project_id=j.project_id left join public.social_publications p on p.id=j.publication_id and p.project_id=j.project_id where b.id=j.batch_revision_id and b.project_id=j.project_id;
$fn$;
create function public.social_schedule_batch_view(b public.social_schedule_batches) returns jsonb language plpgsql stable security invoker set search_path='' as $fn$
declare a public.social_schedule_decisions;jobs jsonb;revoked boolean;
begin
 select * into a from public.social_schedule_decisions where batch_revision_id=b.id and project_id=b.project_id and action='approve';
 revoked=exists(select 1 from public.social_schedule_decisions where approval_id=a.id and action='revoke');
 select coalesce(jsonb_agg(jsonb_build_object('id',j.id,'batchId',b.batch_id,'postId',j.post_id,'channel',j.channel,'state',j.state,'scheduledAt',j.scheduled_at,'expiresAt',j.expires_at,'publicationId',j.publication_id,'reason',j.reason,'version',j.version) order by j.scheduled_at,j.channel),'[]') into jobs from public.social_schedule_jobs j where j.batch_revision_id=b.id and j.project_id=b.project_id;
 return jsonb_build_object('projectId',b.project_id,'batchId',b.batch_id,'revisionId',b.id,'sha256',b.sha256,'status',case when revoked then 'revoked' when a.id is not null then 'approved' else 'proposal' end,'manifest',b.manifest,'approval',case when a.id is null then null else jsonb_build_object('id',a.id,'approvedBy',a.actor,'approvedAt',a.created_at) end,'jobs',jobs,'version',1+(select count(*) from public.social_schedule_decisions where batch_revision_id=b.id));
end $fn$;
create function public.social_schedule_read(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql stable security invoker set search_path='' as $fn$
declare batches jsonb;rule jsonb;evidence jsonb;
begin
 perform public.social_launch_assert_owner(p_principal,p_input);perform public.social_schedule_fields(p_input,array['projectId']);
 select coalesce(jsonb_agg(public.social_schedule_batch_view(b) order by b.created_at desc),'[]') into batches from (select * from public.social_schedule_batches a where a.project_id=(p_input->>'projectId')::uuid and not exists(select 1 from public.social_schedule_batches later where later.batch_id=a.batch_id and later.sequence>a.sequence) order by a.created_at desc limit 100) b;
 select r.rule into rule from public.social_monthly_release_rules r where r.project_id=(p_input->>'projectId')::uuid;
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'releaseMonth',e.release_month,'catalogSha256',e.catalog_sha256,'kind',e.kind,'verifiedAt',e.verified_at) order by e.verified_at desc),'[]') into evidence from (select * from public.social_monthly_release_evidence where project_id=(p_input->>'projectId')::uuid order by verified_at desc limit 24) e;
 return jsonb_build_object('projectId',p_input->>'projectId','batches',batches,'monthlyRule',rule,'releaseEvidence',evidence);
end $fn$;

create function public.social_schedule_cancel_jobs(p_approval uuid,p_actor uuid,p_reason text) returns void language plpgsql security invoker set search_path='' as $fn$
declare j public.social_schedule_jobs;r public.social_publications;next_state text;old_state text;
begin
 for j in select * from public.social_schedule_jobs where approval_id=p_approval and state not in ('published','failed','uncertain','cancelled') for update loop
  select * into r from public.social_publications where id=j.publication_id for update;
  next_state=case when r.state='published' then 'published' when r.state in ('creating','publishing','uncertain') then 'uncertain' else 'cancelled' end;
  if r.state in ('creating','publishing') then
   old_state=r.state;
   update public.social_publications set state='uncertain',version=version+1,updated_at=public.social_schedule_now(),failure_code='receipt_unavailable',capability_hash=null,capability_expires_at=null where id=r.id returning * into r;
   insert into public.social_publication_events(publication_id,project_id,event,from_state,to_state,version,actor,details) values(r.id,r.project_id,'uncertain',old_state,'uncertain',r.version,p_actor,jsonb_build_object('reason',p_reason,'jobId',j.id));
  end if;
  update public.social_schedule_jobs set state=next_state,version=version+1,reason=p_reason,claim_id=null,lease_expires_at=null,updated_at=public.social_schedule_now() where id=j.id;
  insert into public.social_schedule_events(project_id,job_id,batch_revision_id,event,actor_kind,actor,details) values(j.project_id,j.id,j.batch_revision_id,'revoked','owner',p_actor,jsonb_build_object('reason',p_reason,'state',next_state));
 end loop;
end $fn$;
create function public.social_schedule_propose(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare project uuid=(p_input->>'projectId')::uuid;previous public.social_schedule_batches;b public.social_schedule_batches;a public.social_schedule_decisions;batch uuid;seq integer;
begin
 perform public.social_launch_assert_owner(p_principal,p_input);
 perform public.social_schedule_fields(p_input,array['projectId','manifest','expectedRevisionId','idempotencyKey']);
 if coalesce(p_input->>'idempotencyKey','') !~ '^[A-Za-z0-9_-]{1,100}$' then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
 perform 1 from public.projects where id=project for update;perform public.social_launch_assert_owner(p_principal,p_input);perform public.social_content_active(project);
 select * into b from public.social_schedule_batches where project_id=project and idempotency_key=p_input->>'idempotencyKey';
 if b.id is not null then if b.input_data is distinct from p_input then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;return public.social_schedule_batch_view(b);end if;
 perform public.social_schedule_validate_manifest(project,p_input->'manifest');
 if p_input->>'expectedRevisionId' is null then batch=gen_random_uuid();seq=1;
 else
  select * into previous from public.social_schedule_batches where id=(p_input->>'expectedRevisionId')::uuid and project_id=project;
  if previous.id is null or exists(select 1 from public.social_schedule_batches where batch_id=previous.batch_id and sequence>previous.sequence) then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;
  batch=previous.batch_id;seq=previous.sequence+1;
  select * into a from public.social_schedule_decisions d where d.batch_revision_id=previous.id and d.action='approve' and not exists(select 1 from public.social_schedule_decisions revoke where revoke.approval_id=d.id);
  if a.id is not null then
   insert into public.social_schedule_decisions(project_id,batch_revision_id,action,actor,approval_id,reason,idempotency_key,input_data)
   values(project,previous.id,'revoke',(p_principal->>'userId')::uuid,a.id,'revision_changed','revision-'||a.id,jsonb_build_object('newProposalKey',p_input->>'idempotencyKey'));
   perform public.social_schedule_cancel_jobs(a.id,(p_principal->>'userId')::uuid,'revision_changed');
  end if;
 end if;
 insert into public.social_schedule_batches(batch_id,project_id,sequence,manifest,sha256,created_by,idempotency_key,input_data)
 values(batch,project,seq,p_input->'manifest',encode(sha256(convert_to(public.social_schedule_canonical(p_input->'manifest'),'UTF8')),'hex'),(p_principal->>'userId')::uuid,p_input->>'idempotencyKey',p_input) returning * into b;
 insert into public.social_schedule_events(project_id,batch_revision_id,event,actor_kind,actor) values(project,b.id,'proposed','owner',(p_principal->>'userId')::uuid);
 return public.social_schedule_batch_view(b);
end $fn$;
create function public.social_schedule_approve(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare project uuid=(p_input->>'projectId')::uuid;b public.social_schedule_batches;a public.social_schedule_decisions;v jsonb;
begin
 perform public.social_launch_assert_owner(p_principal,p_input);
 perform public.social_schedule_fields(p_input,array['projectId','batchId','revisionId','sha256','confirmed','idempotencyKey']);
 if p_input->'confirmed' is distinct from 'true'::jsonb or coalesce(p_input->>'idempotencyKey','') !~ '^[A-Za-z0-9_-]{1,100}$' then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
 perform 1 from public.projects where id=project for update;perform public.social_launch_assert_owner(p_principal,p_input);perform public.social_content_active(project);
 select * into b from public.social_schedule_batches where id=(p_input->>'revisionId')::uuid and batch_id=(p_input->>'batchId')::uuid and project_id=project and sha256=p_input->>'sha256';
 if b.id is null or exists(select 1 from public.social_schedule_batches where batch_id=b.batch_id and sequence>b.sequence) then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;
 select * into a from public.social_schedule_decisions where project_id=project and idempotency_key=p_input->>'idempotencyKey';
 if a.id is not null then if a.input_data is distinct from p_input then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;return public.social_schedule_batch_view(b);end if;
 if exists(select 1 from public.social_schedule_decisions where batch_revision_id=b.id) then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;
 perform public.social_schedule_validate_manifest(project,b.manifest);
 -- An occasion has one immutable identity across all approved batches.
 if exists(select 1 from (
  select j.occasion_id::text occasion_id,j.channel,j.scheduled_at,j.item->>'kind' kind,(j.item->'releaseCondition')::text condition from public.social_schedule_jobs j where j.project_id=project and j.state<>'cancelled'
  union all select mi.value->>'occasionId',mi.value->>'channel',(mi.value->>'scheduledAt')::timestamptz,mi.value->>'kind',(mi.value->'releaseCondition')::text from jsonb_array_elements(b.manifest->'items') mi(value)
 ) combined group by occasion_id having count(*)>2 or count(*)>count(distinct channel) or count(distinct scheduled_at)>1 or count(distinct kind)>1 or count(distinct condition)>1) then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;
 if exists(select 1 from (
  select j.occasion_id::text occasion_id,j.scheduled_at from public.social_schedule_jobs j where j.project_id=project and j.state<>'cancelled'
  union all select mi.value->>'occasionId',(mi.value->>'scheduledAt')::timestamptz from jsonb_array_elements(b.manifest->'items') mi(value)
 ) occasions group by date_trunc('week',scheduled_at at time zone 'Europe/Stockholm') having count(distinct occasion_id)>3) then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;
 if exists(select 1 from jsonb_array_elements(b.manifest->'items') mi(value) join public.social_publications p on p.project_id=project and p.post_id=(mi.value->>'postId')::uuid) then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;
 insert into public.social_schedule_decisions(project_id,batch_revision_id,action,actor,idempotency_key,input_data)
 values(project,b.id,'approve',(p_principal->>'userId')::uuid,p_input->>'idempotencyKey',p_input) returning * into a;
 for v in select value from jsonb_array_elements(b.manifest->'items') loop
  insert into public.social_schedule_jobs(project_id,batch_revision_id,approval_id,post_id,revision_id,revision_sha256,channel,occasion_id,scheduled_at,expires_at,item,release_month)
  values(project,b.id,a.id,(v->>'postId')::uuid,(v->>'revisionId')::uuid,v->>'sha256',v->>'channel',(v->>'occasionId')::uuid,(v->>'scheduledAt')::timestamptz,(v->>'expiresAt')::timestamptz,v,v->'releaseCondition'->>'releaseMonth');
 end loop;
 insert into public.social_schedule_events(project_id,batch_revision_id,event,actor_kind,actor,details) values(project,b.id,'approved','owner',a.actor,jsonb_build_object('approvalId',a.id,'manifestSha256',b.sha256));
 return public.social_schedule_batch_view(b);
end $fn$;
create function public.social_schedule_revoke(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare project uuid=(p_input->>'projectId')::uuid;b public.social_schedule_batches;a public.social_schedule_decisions;view jsonb;
begin
 perform public.social_launch_assert_owner(p_principal,p_input);perform public.social_schedule_fields(p_input,array['projectId','batchId','expectedVersion']);
 perform 1 from public.projects where id=project for update;perform public.social_launch_assert_owner(p_principal,p_input);
 select * into b from public.social_schedule_batches where project_id=project and batch_id=(p_input->>'batchId')::uuid order by sequence desc limit 1;
 if b.id is null then raise exception 'SOCIAL_SCHEDULE_NOT_FOUND' using errcode='P0002';end if;
 view=public.social_schedule_batch_view(b);
 if (view->>'version')::integer<>(p_input->>'expectedVersion')::integer then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;
 if view->>'status'='revoked' then return view;end if;
 select * into a from public.social_schedule_decisions where batch_revision_id=b.id and action='approve';
 if a.id is null then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;
 insert into public.social_schedule_decisions(project_id,batch_revision_id,action,actor,approval_id,reason,idempotency_key,input_data)
 values(project,b.id,'revoke',(p_principal->>'userId')::uuid,a.id,'owner_revoked','revoke-'||a.id,p_input);
 perform public.social_schedule_cancel_jobs(a.id,(p_principal->>'userId')::uuid,'owner_revoked');
 return public.social_schedule_batch_view(b);
end $fn$;
create function public.social_schedule_monthly_rule_save(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
begin
 perform public.social_launch_assert_owner(p_principal,p_input);perform public.social_schedule_fields(p_input,array['projectId','rule']);
 perform public.social_schedule_fields(p_input->'rule',array['dayOfMonth','localTime','timeZone','channels','enabled']);
 if (p_input->'rule')-'enabled' is distinct from '{"dayOfMonth":1,"localTime":"20:30","timeZone":"Europe/Stockholm","channels":["facebook","instagram"]}'::jsonb or jsonb_typeof(p_input->'rule'->'enabled') is distinct from 'boolean' then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
 perform 1 from public.projects where id=(p_input->>'projectId')::uuid for update;perform public.social_launch_assert_owner(p_principal,p_input);
 insert into public.social_monthly_release_rules(project_id,rule,updated_by) values((p_input->>'projectId')::uuid,p_input->'rule',(p_principal->>'userId')::uuid)
 on conflict(project_id) do update set rule=excluded.rule,updated_by=excluded.updated_by,updated_at=public.social_schedule_now();
 insert into public.social_schedule_events(project_id,event,actor_kind,actor,details) values((p_input->>'projectId')::uuid,'monthly_rule_saved','owner',(p_principal->>'userId')::uuid,p_input->'rule');
 return p_input->'rule';
end $fn$;
create function public.social_schedule_release_confirm(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare e public.social_monthly_release_evidence;
begin
 perform public.social_launch_assert_owner(p_principal,p_input);perform public.social_schedule_fields(p_input,array['projectId','releaseMonth','catalogSha256','customerViewUrl','confirmed']);
 if p_input->'confirmed' is distinct from 'true'::jsonb or coalesce(p_input->>'releaseMonth','') !~ '^20[0-9]{2}-(0[1-9]|1[0-2])$' or coalesce(p_input->>'catalogSha256','') !~ '^[a-f0-9]{64}$'
 or coalesce(p_input->>'customerViewUrl','') !~ '^https://[a-zA-Z0-9.-]+(/[^[:space:]?#]*)?$' or char_length(p_input->>'customerViewUrl')>2048 then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
 perform 1 from public.projects where id=(p_input->>'projectId')::uuid for update;perform public.social_launch_assert_owner(p_principal,p_input);perform public.social_content_active((p_input->>'projectId')::uuid);
 insert into public.social_monthly_release_evidence(project_id,release_month,catalog_sha256,customer_view_url,verified_by,verified_at)
 values((p_input->>'projectId')::uuid,p_input->>'releaseMonth',p_input->>'catalogSha256',p_input->>'customerViewUrl',(p_principal->>'userId')::uuid,public.social_schedule_now()) returning * into e;
 insert into public.social_schedule_events(project_id,event,actor_kind,actor,details) values(e.project_id,'release_access_confirmed','owner',e.verified_by,jsonb_build_object('evidenceId',e.id,'releaseMonth',e.release_month,'catalogSha256',e.catalog_sha256,'kind',e.kind));
 return jsonb_build_object('id',e.id,'releaseMonth',e.release_month,'catalogSha256',e.catalog_sha256,'kind',e.kind,'verifiedAt',e.verified_at);
end $fn$;

create function public.social_schedule_authority(j public.social_schedule_jobs,p_require_release boolean default true) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare a public.social_schedule_decisions;b public.social_schedule_batches;evidence uuid;t timestamptz=public.social_schedule_now();result jsonb;
begin
 select * into a from public.social_schedule_decisions where id=j.approval_id and project_id=j.project_id and batch_revision_id=j.batch_revision_id and action='approve';
 select * into b from public.social_schedule_batches where id=j.batch_revision_id and project_id=j.project_id;
 if a.id is null or b.id is null or exists(select 1 from public.social_schedule_decisions where approval_id=a.id and action='revoke')
 or exists(select 1 from public.social_schedule_batches where batch_id=b.batch_id and sequence>b.sequence)
 or not exists(select 1 from public.projects where id=j.project_id and owner_id=a.actor)
 then raise exception 'SOCIAL_SCHEDULE_REVIEW_REQUIRED';end if;
 begin perform public.social_content_active(j.project_id);exception when others then raise exception 'SOCIAL_SCHEDULE_STOPPED';end;
 if t<j.scheduled_at then raise exception 'SOCIAL_SCHEDULE_NOT_DUE';end if;
 if t>j.expires_at then raise exception 'SOCIAL_SCHEDULE_EXPIRED';end if;
 perform public.social_schedule_item_guard(j.project_id,j.item);
 if j.release_month is not null then
  select e.id into evidence from public.social_monthly_release_evidence e where e.project_id=j.project_id and e.release_month=j.release_month and e.catalog_sha256=j.item->'releaseCondition'->>'catalogSha256' and e.kind='owner_verified_access' and e.verified_by=a.actor and e.verified_at between t-interval '24 hours' and t order by e.verified_at desc limit 1;
  if p_require_release and evidence is null then raise exception 'SOCIAL_SCHEDULE_RELEASE_REQUIRED';end if;
 end if;
 result=public.social_schedule_snapshot(j);
 return result||jsonb_build_object('releaseEvidenceId',evidence);
end $fn$;
create function public.social_schedule_locked_claim(p_claim jsonb) returns public.social_schedule_jobs language plpgsql security invoker set search_path='' as $fn$
declare j public.social_schedule_jobs;project uuid;
begin
 perform public.social_schedule_fields(p_claim,array['jobId','claimId','version']);
 select project_id into project from public.social_schedule_jobs where id=(p_claim->>'jobId')::uuid;
 if project is null then raise exception 'SOCIAL_SCHEDULE_NOT_FOUND' using errcode='P0002';end if;
 perform 1 from public.projects where id=project for update;
 select * into j from public.social_schedule_jobs where id=(p_claim->>'jobId')::uuid for update;
 if j.state<>'claimed' or j.claim_id is distinct from (p_claim->>'claimId')::uuid or j.version<>(p_claim->>'version')::integer or j.lease_expires_at<=public.social_schedule_now() then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;
 return j;
end $fn$;
create function public.social_schedule_claim(p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare candidate record;j public.social_schedule_jobs;r public.social_publications;t timestamptz=public.social_schedule_now();refusal text;old_state text;
begin
 perform public.social_schedule_fields(p_input,array['workerId','now','dryRun','projectIds']);
 if coalesce(p_input->>'workerId','') !~ '^[A-Za-z0-9_-]{1,100}$' or jsonb_typeof(p_input->'dryRun') is distinct from 'boolean' or jsonb_typeof(p_input->'projectIds') is distinct from 'array' or jsonb_array_length(p_input->'projectIds')>100 or abs(extract(epoch from ((p_input->>'now')::timestamptz-t)))>5 then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
 if p_input->'dryRun'='true'::jsonb then return null;end if;
 for candidate in select id,project_id from public.social_schedule_jobs where project_id::text in(select jsonb_array_elements_text(p_input->'projectIds')) and scheduled_at<=t and (state in ('queued','waiting') or state='claimed' and lease_expires_at<=t)
 and not(state='waiting' and coalesce(reason,'')='release_required' and t<=expires_at and not exists(select 1 from public.social_monthly_release_evidence e join public.social_schedule_decisions a on a.id=public.social_schedule_jobs.approval_id where e.project_id=public.social_schedule_jobs.project_id and e.release_month=public.social_schedule_jobs.release_month and e.catalog_sha256=item->'releaseCondition'->>'catalogSha256' and e.kind='owner_verified_access' and e.verified_by=a.actor and e.verified_at between t-interval '24 hours' and t))
 order by scheduled_at,case when state='waiting' then 1 else 0 end,updated_at,id limit 50 loop
  -- Same lock order as owner mutations: project, then job. A busy project is skipped.
  perform 1 from public.projects where id=candidate.project_id for update skip locked;if not found then continue;end if;
  select * into j from public.social_schedule_jobs where id=candidate.id and (state in ('queued','waiting') or state='claimed' and lease_expires_at<=t) for update skip locked;
  if not found then continue;end if;
  select * into r from public.social_publications where id=j.publication_id for update;
  if r.state in ('published','failed','uncertain','creating','publishing') then
   if r.state in ('creating','publishing') then
    old_state=r.state;
    update public.social_publications set state='uncertain',version=version+1,updated_at=t,failure_code='receipt_unavailable',capability_hash=null,capability_expires_at=null where id=r.id returning * into r;
    insert into public.social_publication_events(publication_id,project_id,event,from_state,to_state,version,actor,actor_kind,job_id,details) values(r.id,r.project_id,'uncertain',old_state,'uncertain',r.version,null,'worker',j.id,jsonb_build_object('reason','lease_expired','workerId',p_input->>'workerId'));
   end if;
   update public.social_schedule_jobs set state=r.state,version=version+1,reason=case when r.state='uncertain' then 'receipt_unavailable' else null end,lease_expires_at=null,updated_at=t where id=j.id;
   insert into public.social_schedule_events(project_id,job_id,batch_revision_id,event,actor_kind,worker_id,details) values(j.project_id,j.id,j.batch_revision_id,'lease_recovered','worker',p_input->>'workerId',jsonb_build_object('state',r.state));
   continue;
  end if;
  if t>j.expires_at then
   update public.social_schedule_jobs set state='missed',version=version+1,reason='time_window_expired',lease_expires_at=null,updated_at=t where id=j.id;
   insert into public.social_schedule_events(project_id,job_id,batch_revision_id,event,actor_kind,worker_id) values(j.project_id,j.id,j.batch_revision_id,'missed','worker',p_input->>'workerId');
   continue;
  end if;
  begin perform public.social_schedule_authority(j,false);
  exception when others then
   refusal=case when sqlerrm like '%SOCIAL_SCHEDULE_STOPPED%' then 'stopped' else 'review_required' end;
   update public.social_schedule_jobs set state='blocked',version=version+1,reason=refusal,lease_expires_at=null,updated_at=t where id=j.id;
   insert into public.social_schedule_events(project_id,job_id,batch_revision_id,event,actor_kind,worker_id,details) values(j.project_id,j.id,j.batch_revision_id,'blocked','worker',p_input->>'workerId',jsonb_build_object('reason',refusal));
   continue;
  end;
  update public.social_schedule_jobs set state='claimed',version=version+1,claim_id=gen_random_uuid(),worker_id=p_input->>'workerId',lease_expires_at=t+interval '90 seconds',reason=null,updated_at=t where id=j.id returning * into j;
  insert into public.social_schedule_events(project_id,job_id,batch_revision_id,event,actor_kind,worker_id,details) values(j.project_id,j.id,j.batch_revision_id,'claimed','worker',j.worker_id,jsonb_build_object('claimId',j.claim_id,'version',j.version));
  return jsonb_build_object('jobId',j.id,'claimId',j.claim_id,'version',j.version,'leaseExpiresAt',j.lease_expires_at,'snapshot',public.social_schedule_snapshot(j));
 end loop;
 return null;
end $fn$;
create function public.social_schedule_authorize_write(p_claim jsonb,p_project_ids jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare j public.social_schedule_jobs;
begin
 j=public.social_schedule_locked_claim(p_claim);
 if jsonb_typeof(p_project_ids) is distinct from 'array' or jsonb_array_length(p_project_ids)>100 or not exists(select 1 from jsonb_array_elements_text(p_project_ids) x where x=j.project_id::text) then raise exception 'SOCIAL_SCHEDULE_DISABLED';end if;
 return public.social_schedule_authority(j,true);
end $fn$;
create function public.social_schedule_peek(p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare j public.social_schedule_jobs;reason text;
begin
 perform public.social_schedule_fields(p_input,array['projectIds']);
 if jsonb_typeof(p_input->'projectIds') is distinct from 'array' or jsonb_array_length(p_input->'projectIds')>100 then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
 select * into j from public.social_schedule_jobs where project_id::text in(select jsonb_array_elements_text(p_input->'projectIds')) and state in ('queued','waiting','claimed') order by scheduled_at,case when state='waiting' then 1 else 0 end,updated_at,id limit 1;
 if j.id is null then return jsonb_build_object('jobId',null,'result','no_jobs');end if;
 if j.state='claimed' and j.lease_expires_at>public.social_schedule_now() then return jsonb_build_object('jobId',j.id,'result','claimed');end if;
 begin perform public.social_schedule_authority(j,true);reason='eligible';
 exception when others then reason=case when sqlerrm like '%SOCIAL_SCHEDULE_RELEASE_REQUIRED%' then 'release_required' when sqlerrm like '%SOCIAL_SCHEDULE_NOT_DUE%' then 'not_due' when sqlerrm like '%SOCIAL_SCHEDULE_EXPIRED%' then 'expired' when sqlerrm like '%SOCIAL_SCHEDULE_STOPPED%' then 'stopped' else 'review_required' end;end;
 return jsonb_build_object('jobId',j.id,'result',reason);
end $fn$;
create function public.social_schedule_receipt(p_input jsonb) returns jsonb language plpgsql stable security invoker set search_path='' as $fn$
declare j public.social_schedule_jobs;r public.social_publications;
begin
 perform public.social_schedule_fields(p_input,array['jobId']);
 select * into j from public.social_schedule_jobs where id=(p_input->>'jobId')::uuid;
 if j.id is null then raise exception 'SOCIAL_SCHEDULE_NOT_FOUND' using errcode='P0002';end if;
 select * into r from public.social_publications where id=j.publication_id and project_id=j.project_id and job_id=j.id;
 return jsonb_build_object('claim',jsonb_build_object('jobId',j.id,'claimId',j.claim_id,'version',j.version,'leaseExpiresAt',j.lease_expires_at,'snapshot',public.social_schedule_snapshot(j)),'publication',case when r.id is null then null else public.social_publication_record(r) end,'jobState',j.state);
end $fn$;

create function public.social_schedule_step(p_claim jsonb,p_step jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare j public.social_schedule_jobs;r public.social_publications;a public.social_schedule_decisions;action text=p_step->>'action';old_state text;next_state text;snapshot jsonb;job_state text;checkpoint_reason text;
begin
 perform public.social_schedule_fields(p_step,array['action'],array['expectedVersion','capabilityHash','containerId','providerId','permalink','failureCode','reason']);
 if action not in ('prepare','claim_create','container_ready','claim_publish','complete','fail','uncertain','confirm_published','checkpoint') then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
 j=public.social_schedule_locked_claim(p_claim);
 select * into r from public.social_publications where id=j.publication_id and job_id=j.id and project_id=j.project_id for update;
 if action='prepare' then
  perform public.social_schedule_fields(p_step,array['action']);
  snapshot=public.social_schedule_authority(j,true);
  if r.id is null then
   select * into a from public.social_schedule_decisions where id=j.approval_id and project_id=j.project_id;
   insert into public.social_publications(project_id,post_id,revision_id,sha256,decision_id,binding_id,channel,account_id,account_label,request_input,idempotency_key,requested_by,authority_source,job_id)
   values(j.project_id,j.post_id,j.revision_id,j.revision_sha256,(j.item->>'decisionId')::uuid,(j.item->>'bindingId')::uuid,j.channel,j.item->>'accountId',snapshot->'revision'->'binding'->>'label',jsonb_build_object('jobId',j.id,'approvalId',j.approval_id,'manifestSha256',snapshot->>'manifestSha256'),'schedule-'||j.id,a.actor,'scheduled',j.id) returning * into r;
   insert into public.social_publication_events(publication_id,project_id,event,from_state,to_state,version,actor,actor_kind,job_id,details) values(r.id,r.project_id,'requested',null,r.state,r.version,null,'worker',j.id,jsonb_build_object('approvalId',j.approval_id,'workerId',j.worker_id));
  end if;
 elsif action='checkpoint' then
  if p_step?'reason' and coalesce(p_step->>'reason','') not in ('release_required','stopped','review_required','disabled','budget_exhausted') then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
  if r.state in ('creating','publishing') then
   old_state=r.state;
   update public.social_publications set state='uncertain',version=version+1,updated_at=public.social_schedule_now(),failure_code='receipt_unavailable',capability_hash=null,capability_expires_at=null where id=r.id returning * into r;
   insert into public.social_publication_events(publication_id,project_id,event,from_state,to_state,version,actor,actor_kind,job_id,details) values(r.id,r.project_id,'uncertain',old_state,'uncertain',r.version,null,'worker',j.id,jsonb_build_object('workerId',j.worker_id,'reason','checkpoint_lost'));
  end if;
 else
  if r.id is null or jsonb_typeof(p_step->'expectedVersion') is distinct from 'number' then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;
  if r.version<>(p_step->>'expectedVersion')::integer then return public.social_schedule_receipt(jsonb_build_object('jobId',j.id));end if;
  old_state=r.state;
  next_state=case
   when action='claim_create' and r.state='requested' then case when r.channel='instagram' then 'creating' else 'publishing' end
   when action='container_ready' and r.channel='instagram' and r.state='creating' then 'processing'
   when action='claim_publish' and r.channel='instagram' and r.state='processing' and r.container_id is not null then 'publishing'
   when action='complete' and r.state='publishing' then 'published'
   when action='fail' and r.state in ('creating','processing','publishing') then 'failed'
   when action='uncertain' and r.state in ('creating','publishing') then 'uncertain'
   when action='confirm_published' and r.channel='instagram' and r.container_id is not null and r.state in ('processing','publishing','uncertain') then 'published'
   else null end;
  if next_state is null then return public.social_schedule_receipt(jsonb_build_object('jobId',j.id));end if;
  if action in ('claim_create','claim_publish') then snapshot=public.social_schedule_authority(j,true);end if;
  if action='claim_create' then
   if coalesce(p_step->>'capabilityHash','') !~ '^[a-f0-9]{64}$' then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
   r.capability_hash=p_step->>'capabilityHash';r.capability_expires_at=least(public.social_schedule_now()+interval '15 minutes',j.expires_at);
  end if;
  if action='container_ready' then
   if coalesce(p_step->>'containerId','') !~ '^[0-9]{1,80}$' then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;r.container_id=p_step->>'containerId';
  end if;
  if action='complete' then
   if coalesce(p_step->>'providerId','') !~ '^[0-9]{1,80}(_[0-9]{1,80})?$' or p_step->>'permalink' is not null and not(case when r.channel='instagram' then p_step->>'permalink' ~ '^https://www[.]instagram[.]com/[^[:space:]]+$' else p_step->>'permalink' ~ '^https://www[.]facebook[.]com/[^[:space:]]+$' end) then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;
   r.provider_id=p_step->>'providerId';r.permalink=p_step->>'permalink';r.confirmation='provider_id';r.failure_code=null;
  end if;
  if action='confirm_published' then r.confirmation='container_status';r.failure_code=null;end if;
  if action in ('fail','uncertain') then
   if coalesce(p_step->>'failureCode','') not in ('provider_denied','provider_unavailable','invalid_response','receipt_unavailable') then raise exception 'SOCIAL_SCHEDULE_INVALID_BODY';end if;r.failure_code=p_step->>'failureCode';
  end if;
  if next_state in ('published','failed','uncertain') then r.capability_hash=null;r.capability_expires_at=null;end if;
  update public.social_publications set state=next_state,version=version+1,updated_at=public.social_schedule_now(),container_id=r.container_id,provider_id=r.provider_id,permalink=r.permalink,failure_code=r.failure_code,confirmation=r.confirmation,capability_hash=r.capability_hash,capability_expires_at=r.capability_expires_at where id=r.id returning * into r;
  insert into public.social_publication_events(publication_id,project_id,event,from_state,to_state,version,actor,actor_kind,job_id,details)
  values(r.id,r.project_id,action,old_state,r.state,r.version,null,'worker',j.id,jsonb_build_object('approvalId',j.approval_id,'workerId',j.worker_id,'releaseEvidenceId',snapshot->>'releaseEvidenceId'));
 end if;
 checkpoint_reason=p_step->>'reason';
 job_state=case when r.state in ('published','failed','uncertain') then r.state
  when action='checkpoint' and checkpoint_reason in ('stopped','review_required','disabled') then 'blocked'
  when action='checkpoint' and public.social_schedule_now()>j.expires_at then 'missed'
  when action='checkpoint' then 'waiting' else 'claimed' end;
 update public.social_schedule_jobs set publication_id=r.id,state=job_state,version=version+1,reason=checkpoint_reason,lease_expires_at=case when job_state='claimed' then lease_expires_at else null end,updated_at=public.social_schedule_now() where id=j.id returning * into j;
 insert into public.social_schedule_events(project_id,job_id,batch_revision_id,event,actor_kind,worker_id,details)
 values(j.project_id,j.id,j.batch_revision_id,action,'worker',j.worker_id,jsonb_build_object('state',j.state,'publicationId',r.id,'publicationVersion',r.version,'reason',checkpoint_reason,'releaseEvidenceId',snapshot->>'releaseEvidenceId'));
 return public.social_schedule_receipt(jsonb_build_object('jobId',j.id));
end $fn$;
-- All application helpers and entry points are explicit server-only privileges.
do $grants$ declare f record;begin
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'social_schedule_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  execute format('grant execute on function %s to service_role',f.signature);
 end loop;
end $grants$;

-- Manual mutations never consume queue authority; media and history remain scoped.
create or replace function public.social_publication_step(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare r public.social_publications;old_state text;action text;next_state text;c public.social_content_revisions;
begin
 perform public.social_launch_assert_owner(p_principal,p_input);
 if exists(select 1 from jsonb_object_keys(p_input) k where k not in ('projectId','postId','publicationId','expectedVersion','action','capabilityHash','containerId','providerId','permalink','failureCode'))
 or coalesce(p_input->>'action','') not in ('claim_create','container_ready','claim_publish','complete','fail','uncertain','confirm_published')
 or jsonb_typeof(p_input->'expectedVersion') is distinct from 'number' then raise exception 'SOCIAL_PUBLICATION_INVALID_BODY';end if;
 perform 1 from public.projects where id=(p_input->>'projectId')::uuid for update;
 perform public.social_launch_assert_owner(p_principal,p_input);
 select * into r from public.social_publications where id=(p_input->>'publicationId')::uuid and project_id=(p_input->>'projectId')::uuid and post_id=(p_input->>'postId')::uuid for update;
 if not found then raise exception 'SOCIAL_PUBLICATION_NOT_FOUND' using errcode='P0002';end if;
 if r.authority_source='scheduled' then raise exception 'SOCIAL_PUBLICATION_REVIEW_REQUIRED';end if;
 if r.version<>(p_input->>'expectedVersion')::integer then return jsonb_build_object('changed',false,'record',public.social_publication_record(r));end if;
 action=p_input->>'action';old_state=r.state;
 next_state=case
  when action='claim_create' and r.state='requested' then case when r.channel='instagram' then 'creating' else 'publishing' end
  when action='container_ready' and r.channel='instagram' and r.state='creating' then 'processing'
  when action='claim_publish' and r.channel='instagram' and r.state='processing' then 'publishing'
  when action='complete' and r.state='publishing' then 'published'
  when action='fail' and r.state in ('creating','processing','publishing') then 'failed'
  when action='uncertain' and r.state in ('creating','publishing') then 'uncertain'
  when action='confirm_published' and r.channel='instagram' and r.container_id is not null and r.state in ('processing','publishing','uncertain') then 'published'
  else null end;
 if next_state is null then return jsonb_build_object('changed',false,'record',public.social_publication_record(r));end if;
 if action in ('claim_create','claim_publish') then
  c=public.social_publication_guard(p_principal,r.request_input);
  if action='claim_create' and c.draft->>'format'='image' then
   if coalesce(p_input->>'capabilityHash','') !~ '^[a-f0-9]{64}$' then raise exception 'SOCIAL_PUBLICATION_INVALID_BODY';end if;
   r.capability_hash=p_input->>'capabilityHash';r.capability_expires_at=now()+interval '15 minutes';
  end if;
 end if;
 if action='container_ready' then
  if coalesce(p_input->>'containerId','') !~ '^[0-9]{1,80}$' then raise exception 'SOCIAL_PUBLICATION_INVALID_BODY';end if;r.container_id=p_input->>'containerId';
 end if;
 if action='claim_publish' and r.container_id is null then raise exception 'SOCIAL_PUBLICATION_INVALID_BODY';end if;
 if action='complete' then
  if coalesce(p_input->>'providerId','') !~ '^[0-9]{1,80}(_[0-9]{1,80})?$'
  or p_input->>'permalink' is not null and not(case when r.channel='instagram' then p_input->>'permalink' ~ '^https://www[.]instagram[.]com/[^[:space:]]+$' else p_input->>'permalink' ~ '^https://www[.]facebook[.]com/[^[:space:]]+$' end)
  then raise exception 'SOCIAL_PUBLICATION_INVALID_BODY';end if;
  r.provider_id=p_input->>'providerId';r.permalink=p_input->>'permalink';r.confirmation='provider_id';r.failure_code=null;
 end if;
 if action='confirm_published' then r.confirmation='container_status';r.failure_code=null;end if;
 if action in ('fail','uncertain') then
  if coalesce(p_input->>'failureCode','') not in ('provider_denied','provider_unavailable','invalid_response','receipt_unavailable') then raise exception 'SOCIAL_PUBLICATION_INVALID_BODY';end if;r.failure_code=p_input->>'failureCode';
 end if;
 if next_state in ('published','failed') then r.capability_hash=null;r.capability_expires_at=null;end if;
 update public.social_publications set state=next_state,version=version+1,updated_at=now(),container_id=r.container_id,provider_id=r.provider_id,permalink=r.permalink,failure_code=r.failure_code,confirmation=r.confirmation,capability_hash=r.capability_hash,capability_expires_at=r.capability_expires_at where id=r.id returning * into r;
 insert into public.social_publication_events(publication_id,project_id,event,from_state,to_state,version,actor) values(r.id,r.project_id,action,old_state,r.state,r.version,(p_principal->>'userId')::uuid);
 return jsonb_build_object('changed',true,'record',public.social_publication_record(r));
end $fn$;
create or replace function public.social_publication_prepare(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare r public.social_publications;c public.social_content_revisions;
begin
 perform public.social_launch_assert_owner(p_principal,p_input);
 if (select count(*) from jsonb_object_keys(p_input))<>8 or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('projectId','postId','revisionId','sha256','decisionId','bindingId','idempotencyKey','confirmed'))
 or p_input->'confirmed' is distinct from 'true'::jsonb or jsonb_typeof(p_input->'idempotencyKey') is distinct from 'string' or p_input->>'idempotencyKey' !~ '^[A-Za-z0-9_-]{1,100}$' then raise exception 'SOCIAL_PUBLICATION_INVALID_BODY';end if;
 perform 1 from public.projects where id=(p_input->>'projectId')::uuid for update;
 perform public.social_launch_assert_owner(p_principal,p_input);
 if not exists(select 1 from public.social_content_posts where id=(p_input->>'postId')::uuid and project_id=(p_input->>'projectId')::uuid) then raise exception 'SOCIAL_PUBLICATION_NOT_FOUND' using errcode='P0002';end if;
 select * into r from public.social_publications where project_id=(p_input->>'projectId')::uuid and idempotency_key=p_input->>'idempotencyKey';
 if r.id is null then select * into r from public.social_publications where post_id=(p_input->>'postId')::uuid and project_id=(p_input->>'projectId')::uuid;end if;
 if r.id is not null then
  if r.authority_source='scheduled' then raise exception 'SOCIAL_PUBLICATION_REVIEW_REQUIRED';end if;
  if r.request_input-'idempotencyKey' is distinct from p_input-'idempotencyKey' then raise exception 'SOCIAL_PUBLICATION_CONFLICT';end if;
  return public.social_publication_record(r);
 end if;
 c=public.social_publication_guard(p_principal,p_input);
 insert into public.social_publications(project_id,post_id,revision_id,sha256,decision_id,binding_id,channel,account_id,account_label,request_input,idempotency_key,requested_by)
 values(c.project_id,c.post_id,c.id,c.sha256,(p_input->>'decisionId')::uuid,c.binding_id,c.draft->>'channel',c.binding->>'accountId',c.binding->>'label',p_input,p_input->>'idempotencyKey',(p_principal->>'userId')::uuid) returning * into r;
 insert into public.social_publication_events(publication_id,project_id,event,from_state,to_state,version,actor) values(r.id,r.project_id,'requested',null,r.state,r.version,(p_principal->>'userId')::uuid);
 return public.social_publication_record(r);
end $fn$;
create or replace function public.social_publication_media_lookup(p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare r public.social_publications;c public.social_content_revisions;a public.assets;j public.social_schedule_jobs;
begin
 if jsonb_typeof(p_input) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_input))<>2 or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('publicationId','keyHash')) or coalesce(p_input->>'keyHash','') !~ '^[a-f0-9]{64}$' then return null;end if;
 select * into r from public.social_publications where id=(p_input->>'publicationId')::uuid and capability_hash=p_input->>'keyHash' and capability_expires_at>now() and state in ('creating','processing','publishing','uncertain');
 if not found then return null;end if;
 if r.authority_source='scheduled' then
  select * into j from public.social_schedule_jobs where id=r.job_id and project_id=r.project_id and publication_id=r.id and state in ('claimed','waiting');
  if j.id is null then return null;end if;
  begin perform public.social_schedule_authority(j,true);exception when others then return null;end;
 end if;
 begin perform public.social_content_active(r.project_id);exception when others then return null;end;
 select * into c from public.social_content_revisions where id=r.revision_id and post_id=r.post_id and project_id=r.project_id;
 if jsonb_array_length(c.media)<>1 then return null;end if;
 select * into a from public.assets where id=(c.media->0->>'id')::uuid and project_id=r.project_id and status='active' and kind='image' and mime_type='image/jpeg' and checksum_sha256=c.media->0->>'sha256' and byte_size between 1 and 8388608;
 if not found then return null;end if;
 return jsonb_build_object('projectId',a.project_id,'assetId',a.id,'sha256',a.checksum_sha256,'mimeType',a.mime_type,'byteSize',a.byte_size,'bucket',a.storage_bucket,'path',a.storage_path);
end $fn$;
create or replace function public.social_publication_reconciliation_complete(p_principal jsonb,p_input jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare r public.social_publications;p public.social_publication_reconciliation_proofs;v jsonb;
begin
 perform public.social_launch_assert_owner(p_principal,p_input);
 if jsonb_typeof(p_input) is distinct from 'object' or (select count(*) from jsonb_object_keys(p_input))<>8 or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('projectId','postId','publicationId','candidateId','expectedVersion','imageConfirmed','candidateHash','readAt'))
 or p_input->'imageConfirmed' is distinct from 'true'::jsonb or jsonb_typeof(p_input->'expectedVersion') is distinct from 'number' or coalesce(p_input->>'candidateHash','') !~ '^[a-f0-9]{64}$'
 then raise exception 'SOCIAL_PUBLICATION_INVALID_BODY';end if;
 v=public.social_publication_reconciliation_inspect(p_principal,jsonb_build_object('projectId',p_input->>'projectId','postId',p_input->>'postId','publicationId',p_input->>'publicationId'));
 select * into r from public.social_publications where id=(p_input->>'publicationId')::uuid for update;
 select * into p from public.social_publication_reconciliation_proofs where id=(p_input->>'candidateId')::uuid and publication_id=r.id and project_id=r.project_id;
 if p.id is null or p.expires_at<clock_timestamp() or p.candidate_hash is distinct from p_input->>'candidateHash'
 or p.revision_id<>r.revision_id or p.revision_sha256<>r.sha256 or p.version<>(p_input->>'expectedVersion')::integer
 or (p_input->>'readAt')::timestamptz not between clock_timestamp()-interval '30 seconds' and clock_timestamp()+interval '5 seconds'
 then raise exception 'SOCIAL_PUBLICATION_CONFLICT';end if;
 if r.state='published' then
  if r.provider_id=p.candidate->>'providerId' and r.permalink=p.candidate->>'permalink' then return public.social_publication_record(r);end if;
  raise exception 'SOCIAL_PUBLICATION_CONFLICT';
 end if;
 if r.state<>'uncertain' or r.version<>p.version then raise exception 'SOCIAL_PUBLICATION_CONFLICT';end if;
 update public.social_publications set state='published',version=version+1,updated_at=clock_timestamp(),reconciled_at=clock_timestamp(),provider_id=p.candidate->>'providerId',permalink=p.candidate->>'permalink',confirmation='provider_id',failure_code=null,capability_hash=null,capability_expires_at=null where id=r.id returning * into r;
 insert into public.social_publication_events(publication_id,project_id,event,from_state,to_state,version,actor,details)
 values(r.id,r.project_id,'reconcile_verified','uncertain','published',r.version,(p_principal->>'userId')::uuid,jsonb_build_object('revisionId',p.revision_id,'revisionSha256',p.revision_sha256,'reviewedAssetSha256',p.reviewed_asset_sha256,'accountId',r.account_id,'providerId',r.provider_id,'candidateHash',p.candidate_hash,'readAt',p_input->>'readAt'));
 if r.authority_source='scheduled' then
  update public.social_schedule_jobs set state='published',version=version+1,reason=null,lease_expires_at=null,updated_at=public.social_schedule_now() where id=r.job_id and project_id=r.project_id and publication_id=r.id;
  insert into public.social_schedule_events(project_id,job_id,event,actor_kind,actor,details) values(r.project_id,r.job_id,'receipt_reconciled','owner',(p_principal->>'userId')::uuid,jsonb_build_object('publicationId',r.id,'providerId',r.provider_id));
 end if;
 return public.social_publication_record(r);
end $fn$;

-- History-only recovery: an expired claim can never authorize another provider POST.
-- CAS remains bound to the same claim/version; only persisted evidence chooses state.
create function public.social_schedule_recover_checkpoint(p_claim jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare project uuid;j public.social_schedule_jobs;r public.social_publications;old_state text;next_state text;
begin
 perform public.social_schedule_fields(p_claim,array['jobId','claimId','version']);
 select project_id into project from public.social_schedule_jobs where id=(p_claim->>'jobId')::uuid;
 if project is null then raise exception 'SOCIAL_SCHEDULE_NOT_FOUND' using errcode='P0002';end if;
 perform 1 from public.projects where id=project for update;
 select * into j from public.social_schedule_jobs where id=(p_claim->>'jobId')::uuid for update;
 if j.claim_id is distinct from (p_claim->>'claimId')::uuid or j.version<>(p_claim->>'version')::integer then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;
 if j.state in ('published','failed','uncertain','blocked','cancelled','missed') then return public.social_schedule_receipt(jsonb_build_object('jobId',j.id));end if;
 if j.state<>'claimed' then raise exception 'SOCIAL_SCHEDULE_CONFLICT';end if;
 select * into r from public.social_publications where id=j.publication_id and project_id=j.project_id and job_id=j.id for update;
 if r.state in ('creating','publishing') then
  old_state=r.state;
  update public.social_publications set state='uncertain',version=version+1,updated_at=public.social_schedule_now(),failure_code='receipt_unavailable',capability_hash=null,capability_expires_at=null where id=r.id returning * into r;
  insert into public.social_publication_events(publication_id,project_id,event,from_state,to_state,version,actor,actor_kind,job_id,details)
  values(r.id,r.project_id,'uncertain',old_state,'uncertain',r.version,null,'worker',j.id,jsonb_build_object('workerId',j.worker_id,'reason','checkpoint_recovery'));
 end if;
 next_state=case when r.state in ('published','failed','uncertain') then r.state when public.social_schedule_now()>j.expires_at then 'missed' else 'waiting' end;
 update public.social_schedule_jobs set state=next_state,version=version+1,reason=case when next_state='uncertain' then 'receipt_unavailable' when next_state='missed' then 'time_window_expired' else null end,lease_expires_at=null,updated_at=public.social_schedule_now() where id=j.id;
 insert into public.social_schedule_events(project_id,job_id,batch_revision_id,event,actor_kind,worker_id,details)
 values(j.project_id,j.id,j.batch_revision_id,'checkpoint_recovered','worker',j.worker_id,jsonb_build_object('claimId',j.claim_id,'state',next_state,'publicationId',r.id));
 return public.social_schedule_receipt(jsonb_build_object('jobId',j.id));
end $fn$;
revoke all on function public.social_schedule_recover_checkpoint(jsonb) from public,anon,authenticated;
grant execute on function public.social_schedule_recover_checkpoint(jsonb) to service_role;

create or replace function public.social_schedule_review_current(b public.social_schedule_batches) returns boolean language plpgsql stable security invoker set search_path='' as $fn$
declare item jsonb;
begin
 for item in select value from jsonb_array_elements(b.manifest->'items') loop perform public.social_schedule_item_guard(b.project_id,item);end loop;
 return true;
exception when others then return false;
end $fn$;
create or replace function public.social_schedule_review_items(b public.social_schedule_batches) returns jsonb language sql stable security invoker set search_path='' as $fn$
 select coalesce(jsonb_agg(jsonb_build_object('item',mi.value,'revision',case when c.id is null then null else public.social_schedule_revision(c) end) order by mi.ord),'[]')
 from jsonb_array_elements(b.manifest->'items') with ordinality mi(value,ord)
 left join public.social_content_revisions c on c.id=(mi.value->>'revisionId')::uuid and c.post_id=(mi.value->>'postId')::uuid and c.project_id=b.project_id and c.sha256=mi.value->>'sha256';
$fn$;
create or replace function public.social_schedule_batch_view(b public.social_schedule_batches) returns jsonb language plpgsql stable security invoker set search_path='' as $fn$
declare a public.social_schedule_decisions;jobs jsonb;revoked boolean;
begin
 select * into a from public.social_schedule_decisions where batch_revision_id=b.id and project_id=b.project_id and action='approve';
 revoked=exists(select 1 from public.social_schedule_decisions where approval_id=a.id and action='revoke');
 select coalesce(jsonb_agg(jsonb_build_object('id',j.id,'batchId',b.batch_id,'postId',j.post_id,'channel',j.channel,'state',j.state,'scheduledAt',j.scheduled_at,'expiresAt',j.expires_at,'publicationId',j.publication_id,'reason',j.reason,'version',j.version,'permalink',p.permalink,'publicationState',p.state) order by j.scheduled_at,j.channel),'[]') into jobs from public.social_schedule_jobs j left join public.social_publications p on p.id=j.publication_id and p.project_id=j.project_id where j.batch_revision_id=b.id and j.project_id=b.project_id;
 return jsonb_build_object('projectId',b.project_id,'batchId',b.batch_id,'revisionId',b.id,'sha256',b.sha256,'status',case when revoked then 'revoked' when a.id is not null then 'approved' else 'proposal' end,'manifest',b.manifest,'review',public.social_schedule_review_items(b),'reviewCurrent',public.social_schedule_review_current(b),'approval',case when a.id is null then null else jsonb_build_object('id',a.id,'approvedBy',a.actor,'approvedAt',a.created_at) end,'jobs',jobs,'version',1+(select count(*) from public.social_schedule_decisions where batch_revision_id=b.id));
end $fn$;
revoke all on function public.social_schedule_review_items(public.social_schedule_batches),public.social_schedule_batch_view(public.social_schedule_batches) from public,anon,authenticated;
grant execute on function public.social_schedule_review_items(public.social_schedule_batches),public.social_schedule_batch_view(public.social_schedule_batches) to service_role;

revoke all on function public.social_schedule_review_current(public.social_schedule_batches) from public,anon,authenticated;grant execute on function public.social_schedule_review_current(public.social_schedule_batches) to service_role;

begin;
-- Historical values remain immutable. Legacy defaults label existing rows without rewriting counts.
alter table public.handlarborsen_marketplace_snapshots
 add column definition_id text not null default 'handlarborsen-legacy-v1',
 add column data_scope text not null default 'legacy_all_organisations',
 add column excluded_test_organisations bigint;
alter table public.handlarborsen_marketplace_snapshots drop constraint handlarborsen_marketplace_snapshots_contract;
alter table public.handlarborsen_marketplace_snapshots add constraint handlarborsen_marketplace_snapshots_contract check(
 window_hours=24 and ((schema_version=1 and definition_id='handlarborsen-legacy-v1' and data_scope='legacy_all_organisations' and excluded_test_organisations is null)
 or (schema_version=2 and definition_id='handlarborsen-production-v2' and data_scope='production_excluding_quarantined_test'
 and (excluded_test_organisations is null or excluded_test_organisations between 0 and 9007199254740991))));
-- Each definition has its own same-day quality/observation guard; old and new callers coexist.
alter table public.handlarborsen_marketplace_snapshots drop constraint handlarborsen_marketplace_snapshots_project_unique;
alter table public.handlarborsen_marketplace_snapshots add constraint handlarborsen_marketplace_snapshots_project_unique unique(project_id,snapshot_date,definition_id);

CREATE OR REPLACE FUNCTION public.handlarborsen_store_marketplace_snapshot(
  p_snapshot_date date,
  p_observed_at   timestamptz,
  p_unavailable   jsonb,
  p_metrics       jsonb
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $fn$
DECLARE
  c_project constant uuid   := '8f673c09-1c8f-4d78-876e-4c14bf1c89b3';
  c_keys    constant text[] := ARRAY[
    'companies_registered_total', 'companies_verified_total', 'vehicles_published_active',
    'vehicles_reserved', 'vehicles_published_last_24h', 'bids_total', 'bids_last_24h',
    'interests_last_24h', 'offers_last_24h', 'deals_completed_total', 'deals_completed_last_24h'
  ];
  v_key          text;
  v_val          jsonb;
  v_null_keys    text[] := ARRAY[]::text[];
  v_unavail_keys text[];
  v_reason       jsonb;
  v_available    integer;
  v_completeness text;
  v_inserted     boolean;
  v_old          record;
  v_old_avail    integer;
  v_outcome      text;
  v_reject       text;
BEGIN
  -- ── Input validation (fixed codes; never echoes input) ──────────────────────────
  IF p_snapshot_date IS NULL OR p_observed_at IS NULL THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:missing_argument' USING ERRCODE = '22023';
  END IF;
  IF p_snapshot_date <> (now() AT TIME ZONE 'UTC')::date THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:not_today' USING ERRCODE = '22023';
  END IF;
  IF (p_observed_at AT TIME ZONE 'UTC')::date <> p_snapshot_date
     OR p_observed_at > now() + interval '10 minutes' THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:observed_at' USING ERRCODE = '22023';
  END IF;

  IF p_metrics IS NULL OR jsonb_typeof(p_metrics) <> 'object'
     OR p_unavailable IS NULL OR jsonb_typeof(p_unavailable) <> 'object' THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:shape' USING ERRCODE = '22023';
  END IF;
  IF (SELECT coalesce(array_agg(k ORDER BY k), ARRAY[]::text[]) FROM jsonb_object_keys(p_metrics) AS k)
     <> (SELECT array_agg(k ORDER BY k) FROM unnest(c_keys) AS k) THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:metric_keys' USING ERRCODE = '22023';
  END IF;

  FOREACH v_key IN ARRAY c_keys LOOP
    v_val := p_metrics -> v_key;
    IF jsonb_typeof(v_val) = 'null' THEN
      v_null_keys := v_null_keys || v_key;
    ELSIF jsonb_typeof(v_val) = 'number' THEN
      -- Non-negative integer only: no sign, fraction or exponent, and below 2^53.
      IF v_val::text !~ '^[0-9]{1,15}$' THEN
        RAISE EXCEPTION 'handlarborsen_snapshot_invalid:metric_value' USING ERRCODE = '22023';
      END IF;
    ELSE
      RAISE EXCEPTION 'handlarborsen_snapshot_invalid:metric_type' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  -- `unavailable` names exactly the null metrics, each with a known reason.
  SELECT coalesce(array_agg(k ORDER BY k), ARRAY[]::text[]) INTO v_unavail_keys
    FROM jsonb_object_keys(p_unavailable) AS k;
  IF v_unavail_keys <> (SELECT coalesce(array_agg(k ORDER BY k), ARRAY[]::text[]) FROM unnest(v_null_keys) AS k) THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:unavailable_keys' USING ERRCODE = '22023';
  END IF;
  FOREACH v_key IN ARRAY v_unavail_keys LOOP
    v_reason := p_unavailable -> v_key;
    IF jsonb_typeof(v_reason) <> 'string' OR (v_reason #>> '{}') NOT IN ('query_failed', 'invalid_count') THEN
      RAISE EXCEPTION 'handlarborsen_snapshot_invalid:unavailable_reason' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  v_available    := array_length(c_keys, 1) - coalesce(array_length(v_null_keys, 1), 0);
  v_completeness := CASE
    WHEN v_available = array_length(c_keys, 1) THEN 'complete'
    WHEN v_available = 0 THEN 'unavailable'
    ELSE 'partial'
  END;

  -- ── Insert-or-decide, serialized on the row ─────────────────────────────────────
  -- A concurrent insert for the same day blocks on the unique index and then sees DO
  -- NOTHING; every later step takes the row lock first, so two runs can never both decide
  -- against the same stale state.
  INSERT INTO public.handlarborsen_marketplace_snapshots (
    project_id, snapshot_date, observed_at, captured_at, schema_version, window_hours,
    completeness, unavailable,
    companies_registered_total, companies_verified_total, vehicles_published_active,
    vehicles_reserved, vehicles_published_last_24h, bids_total, bids_last_24h,
    interests_last_24h, offers_last_24h, deals_completed_total, deals_completed_last_24h
  ) VALUES (
    c_project, p_snapshot_date, p_observed_at, now(), 1, 24,
    v_completeness, p_unavailable,
    (p_metrics ->> 'companies_registered_total')::bigint, (p_metrics ->> 'companies_verified_total')::bigint,
    (p_metrics ->> 'vehicles_published_active')::bigint, (p_metrics ->> 'vehicles_reserved')::bigint,
    (p_metrics ->> 'vehicles_published_last_24h')::bigint, (p_metrics ->> 'bids_total')::bigint,
    (p_metrics ->> 'bids_last_24h')::bigint, (p_metrics ->> 'interests_last_24h')::bigint,
    (p_metrics ->> 'offers_last_24h')::bigint, (p_metrics ->> 'deals_completed_total')::bigint,
    (p_metrics ->> 'deals_completed_last_24h')::bigint
  )
  ON CONFLICT (project_id, snapshot_date,definition_id) DO NOTHING
  RETURNING true INTO v_inserted;

  IF v_inserted THEN
    RETURN jsonb_build_object(
      'outcome', 'inserted', 'stored', true, 'snapshot_date', p_snapshot_date,
      'completeness', v_completeness, 'available_count', v_available
    );
  END IF;

  SELECT completeness, observed_at,
         num_nonnulls(companies_registered_total, companies_verified_total, vehicles_published_active,
                      vehicles_reserved, vehicles_published_last_24h, bids_total, bids_last_24h,
                      interests_last_24h, offers_last_24h, deals_completed_total,
                      deals_completed_last_24h) AS available
    INTO v_old
    FROM public.handlarborsen_marketplace_snapshots
   WHERE project_id = c_project AND snapshot_date = p_snapshot_date AND definition_id='handlarborsen-legacy-v1'
     FOR UPDATE;

  IF NOT FOUND THEN
    -- Unreachable: the row existed a moment ago and no role may delete it.
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:row_vanished' USING ERRCODE = '55000';
  END IF;
  v_old_avail := v_old.available;

  IF v_available > v_old_avail THEN
    v_outcome := 'upgraded';
  ELSIF v_available = v_old_avail AND p_observed_at > v_old.observed_at THEN
    v_outcome := 'refreshed';
  ELSIF v_available = v_old_avail AND p_observed_at = v_old.observed_at THEN
    v_outcome := 'unchanged';
  ELSE
    v_outcome := 'rejected';
    v_reject  := CASE WHEN v_available < v_old_avail THEN 'lower_quality' ELSE 'older_observation' END;
  END IF;

  IF v_outcome IN ('upgraded', 'refreshed') THEN
    UPDATE public.handlarborsen_marketplace_snapshots SET
      observed_at = p_observed_at, captured_at = now(), completeness = v_completeness,
      unavailable = p_unavailable,
      companies_registered_total  = (p_metrics ->> 'companies_registered_total')::bigint,
      companies_verified_total    = (p_metrics ->> 'companies_verified_total')::bigint,
      vehicles_published_active   = (p_metrics ->> 'vehicles_published_active')::bigint,
      vehicles_reserved           = (p_metrics ->> 'vehicles_reserved')::bigint,
      vehicles_published_last_24h = (p_metrics ->> 'vehicles_published_last_24h')::bigint,
      bids_total                  = (p_metrics ->> 'bids_total')::bigint,
      bids_last_24h               = (p_metrics ->> 'bids_last_24h')::bigint,
      interests_last_24h          = (p_metrics ->> 'interests_last_24h')::bigint,
      offers_last_24h             = (p_metrics ->> 'offers_last_24h')::bigint,
      deals_completed_total       = (p_metrics ->> 'deals_completed_total')::bigint,
      deals_completed_last_24h    = (p_metrics ->> 'deals_completed_last_24h')::bigint
     WHERE project_id = c_project AND snapshot_date = p_snapshot_date AND definition_id='handlarborsen-legacy-v1';
  END IF;

  RETURN jsonb_build_object(
    'outcome', v_outcome,
    'stored', v_outcome IN ('upgraded', 'refreshed'),
    'reason', v_reject,
    'snapshot_date', p_snapshot_date,
    'completeness', v_completeness,
    'available_count', v_available,
    'existing_completeness', v_old.completeness,
    'existing_available_count', v_old_avail,
    'existing_observed_at', v_old.observed_at
  );
END;
$fn$;

COMMENT ON FUNCTION public.handlarborsen_store_marketplace_snapshot(date, timestamptz, jsonb, jsonb) IS
  'The only write path to handlarborsen_marketplace_snapshots. Atomic insert-or-decide under a row lock: '
  'a complete report is never replaced by a less complete one, an older observation never replaces a newer '
  'one of equal quality, only today (UTC) is writable. Returns {outcome, stored, ...}. Service role only.';

REVOKE ALL ON FUNCTION public.handlarborsen_store_marketplace_snapshot(date, timestamptz, jsonb, jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.handlarborsen_store_marketplace_snapshot(date, timestamptz, jsonb, jsonb) FROM anon;
REVOKE ALL ON FUNCTION public.handlarborsen_store_marketplace_snapshot(date, timestamptz, jsonb, jsonb) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.handlarborsen_store_marketplace_snapshot(date, timestamptz, jsonb, jsonb) TO service_role;

-- The function is now the only writer. Without INSERT/UPDATE a direct upsert (the P1B code
-- path, or any future caller) cannot bypass the rule. SELECT stays for the report reader.
REVOKE INSERT, UPDATE ON TABLE public.handlarborsen_marketplace_snapshots FROM service_role;

CREATE OR REPLACE FUNCTION public.handlarborsen_store_marketplace_snapshot_v2(
  p_snapshot_date date,
  p_observed_at   timestamptz,
  p_unavailable   jsonb,
  p_metrics       jsonb,
  p_excluded_test_organisations bigint
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $fn$
DECLARE
  c_project constant uuid   := '8f673c09-1c8f-4d78-876e-4c14bf1c89b3';
  c_keys    constant text[] := ARRAY[
    'companies_registered_total', 'companies_verified_total', 'vehicles_published_active',
    'vehicles_reserved', 'vehicles_published_last_24h', 'bids_total', 'bids_last_24h',
    'interests_last_24h', 'offers_last_24h', 'deals_completed_total', 'deals_completed_last_24h'
  ];
  v_key          text;
  v_val          jsonb;
  v_null_keys    text[] := ARRAY[]::text[];
  v_unavail_keys text[];
  v_reason       jsonb;
  v_available    integer;
  v_completeness text;
  v_inserted     boolean;
  v_old          record;
  v_old_avail    integer;
  v_outcome      text;
  v_reject       text;
BEGIN
  IF p_excluded_test_organisations<0 OR p_excluded_test_organisations>9007199254740991 THEN RAISE EXCEPTION 'handlarborsen_snapshot_invalid:excluded_count' USING ERRCODE='22023'; END IF;
  -- ── Input validation (fixed codes; never echoes input) ──────────────────────────
  IF p_snapshot_date IS NULL OR p_observed_at IS NULL THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:missing_argument' USING ERRCODE = '22023';
  END IF;
  IF p_snapshot_date <> (now() AT TIME ZONE 'UTC')::date THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:not_today' USING ERRCODE = '22023';
  END IF;
  IF (p_observed_at AT TIME ZONE 'UTC')::date <> p_snapshot_date
     OR p_observed_at > now() + interval '10 minutes' THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:observed_at' USING ERRCODE = '22023';
  END IF;

  IF p_metrics IS NULL OR jsonb_typeof(p_metrics) <> 'object'
     OR p_unavailable IS NULL OR jsonb_typeof(p_unavailable) <> 'object' THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:shape' USING ERRCODE = '22023';
  END IF;
  IF (SELECT coalesce(array_agg(k ORDER BY k), ARRAY[]::text[]) FROM jsonb_object_keys(p_metrics) AS k)
     <> (SELECT array_agg(k ORDER BY k) FROM unnest(c_keys) AS k) THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:metric_keys' USING ERRCODE = '22023';
  END IF;

  FOREACH v_key IN ARRAY c_keys LOOP
    v_val := p_metrics -> v_key;
    IF jsonb_typeof(v_val) = 'null' THEN
      v_null_keys := v_null_keys || v_key;
    ELSIF jsonb_typeof(v_val) = 'number' THEN
      -- Non-negative integer only: no sign, fraction or exponent, and below 2^53.
      IF v_val::text !~ '^[0-9]{1,15}$' THEN
        RAISE EXCEPTION 'handlarborsen_snapshot_invalid:metric_value' USING ERRCODE = '22023';
      END IF;
    ELSE
      RAISE EXCEPTION 'handlarborsen_snapshot_invalid:metric_type' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  -- `unavailable` names exactly the null metrics, each with a known reason.
  SELECT coalesce(array_agg(k ORDER BY k), ARRAY[]::text[]) INTO v_unavail_keys
    FROM jsonb_object_keys(p_unavailable) AS k;
  IF v_unavail_keys <> (SELECT coalesce(array_agg(k ORDER BY k), ARRAY[]::text[]) FROM unnest(v_null_keys) AS k) THEN
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:unavailable_keys' USING ERRCODE = '22023';
  END IF;
  FOREACH v_key IN ARRAY v_unavail_keys LOOP
    v_reason := p_unavailable -> v_key;
    IF jsonb_typeof(v_reason) <> 'string' OR (v_reason #>> '{}') NOT IN ('query_failed', 'invalid_count') THEN
      RAISE EXCEPTION 'handlarborsen_snapshot_invalid:unavailable_reason' USING ERRCODE = '22023';
    END IF;
  END LOOP;

  v_available    := array_length(c_keys, 1) - coalesce(array_length(v_null_keys, 1), 0);
  v_completeness := CASE
    WHEN v_available = array_length(c_keys, 1) THEN 'complete'
    WHEN v_available = 0 THEN 'unavailable'
    ELSE 'partial'
  END;

  -- ── Insert-or-decide, serialized on the row ─────────────────────────────────────
  -- A concurrent insert for the same day blocks on the unique index and then sees DO
  -- NOTHING; every later step takes the row lock first, so two runs can never both decide
  -- against the same stale state.
  INSERT INTO public.handlarborsen_marketplace_snapshots (
    project_id, snapshot_date, observed_at, captured_at, schema_version, window_hours,
    definition_id,data_scope,excluded_test_organisations,completeness, unavailable,
    companies_registered_total, companies_verified_total, vehicles_published_active,
    vehicles_reserved, vehicles_published_last_24h, bids_total, bids_last_24h,
    interests_last_24h, offers_last_24h, deals_completed_total, deals_completed_last_24h
  ) VALUES (
    c_project, p_snapshot_date, p_observed_at, now(), 2, 24,
    'handlarborsen-production-v2','production_excluding_quarantined_test',p_excluded_test_organisations,
    v_completeness, p_unavailable,
    (p_metrics ->> 'companies_registered_total')::bigint, (p_metrics ->> 'companies_verified_total')::bigint,
    (p_metrics ->> 'vehicles_published_active')::bigint, (p_metrics ->> 'vehicles_reserved')::bigint,
    (p_metrics ->> 'vehicles_published_last_24h')::bigint, (p_metrics ->> 'bids_total')::bigint,
    (p_metrics ->> 'bids_last_24h')::bigint, (p_metrics ->> 'interests_last_24h')::bigint,
    (p_metrics ->> 'offers_last_24h')::bigint, (p_metrics ->> 'deals_completed_total')::bigint,
    (p_metrics ->> 'deals_completed_last_24h')::bigint
  )
  ON CONFLICT (project_id, snapshot_date,definition_id) DO NOTHING
  RETURNING true INTO v_inserted;

  IF v_inserted THEN
    RETURN jsonb_build_object(
      'outcome', 'inserted', 'stored', true, 'snapshot_date', p_snapshot_date,
      'completeness', v_completeness, 'available_count', v_available
    );
  END IF;

  SELECT completeness, observed_at,
         num_nonnulls(companies_registered_total, companies_verified_total, vehicles_published_active,
                      vehicles_reserved, vehicles_published_last_24h, bids_total, bids_last_24h,
                      interests_last_24h, offers_last_24h, deals_completed_total,
                      deals_completed_last_24h) AS available
    INTO v_old
    FROM public.handlarborsen_marketplace_snapshots
   WHERE project_id = c_project AND snapshot_date = p_snapshot_date AND definition_id='handlarborsen-production-v2'
     FOR UPDATE;

  IF NOT FOUND THEN
    -- Unreachable: the row existed a moment ago and no role may delete it.
    RAISE EXCEPTION 'handlarborsen_snapshot_invalid:row_vanished' USING ERRCODE = '55000';
  END IF;
  v_old_avail := v_old.available;

  IF v_available > v_old_avail THEN
    v_outcome := 'upgraded';
  ELSIF v_available = v_old_avail AND p_observed_at > v_old.observed_at THEN
    v_outcome := 'refreshed';
  ELSIF v_available = v_old_avail AND p_observed_at = v_old.observed_at THEN
    v_outcome := 'unchanged';
  ELSE
    v_outcome := 'rejected';
    v_reject  := CASE WHEN v_available < v_old_avail THEN 'lower_quality' ELSE 'older_observation' END;
  END IF;

  IF v_outcome IN ('upgraded', 'refreshed') THEN
    UPDATE public.handlarborsen_marketplace_snapshots SET
      observed_at = p_observed_at, captured_at = now(), completeness = v_completeness,
      excluded_test_organisations=p_excluded_test_organisations,
      unavailable = p_unavailable,
      companies_registered_total  = (p_metrics ->> 'companies_registered_total')::bigint,
      companies_verified_total    = (p_metrics ->> 'companies_verified_total')::bigint,
      vehicles_published_active   = (p_metrics ->> 'vehicles_published_active')::bigint,
      vehicles_reserved           = (p_metrics ->> 'vehicles_reserved')::bigint,
      vehicles_published_last_24h = (p_metrics ->> 'vehicles_published_last_24h')::bigint,
      bids_total                  = (p_metrics ->> 'bids_total')::bigint,
      bids_last_24h               = (p_metrics ->> 'bids_last_24h')::bigint,
      interests_last_24h          = (p_metrics ->> 'interests_last_24h')::bigint,
      offers_last_24h             = (p_metrics ->> 'offers_last_24h')::bigint,
      deals_completed_total       = (p_metrics ->> 'deals_completed_total')::bigint,
      deals_completed_last_24h    = (p_metrics ->> 'deals_completed_last_24h')::bigint
     WHERE project_id = c_project AND snapshot_date = p_snapshot_date AND definition_id='handlarborsen-production-v2';
  END IF;

  RETURN jsonb_build_object(
    'outcome', v_outcome,
    'stored', v_outcome IN ('upgraded', 'refreshed'),
    'reason', v_reject,
    'snapshot_date', p_snapshot_date,
    'completeness', v_completeness,
    'available_count', v_available,
    'existing_completeness', v_old.completeness,
    'existing_available_count', v_old_avail,
    'existing_observed_at', v_old.observed_at
  );
END;
$fn$;

COMMENT ON FUNCTION public.handlarborsen_store_marketplace_snapshot_v2(date, timestamptz, jsonb, jsonb,bigint) IS
  'The only write path to handlarborsen_marketplace_snapshots. Atomic insert-or-decide under a row lock: '
  'a complete report is never replaced by a less complete one, an older observation never replaces a newer '
  'one of equal quality, only today (UTC) is writable. Returns {outcome, stored, ...}. Service role only.';

REVOKE ALL ON FUNCTION public.handlarborsen_store_marketplace_snapshot_v2(date, timestamptz, jsonb, jsonb,bigint) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.handlarborsen_store_marketplace_snapshot_v2(date, timestamptz, jsonb, jsonb,bigint) FROM anon;
REVOKE ALL ON FUNCTION public.handlarborsen_store_marketplace_snapshot_v2(date, timestamptz, jsonb, jsonb,bigint) FROM authenticated;
GRANT EXECUTE ON FUNCTION public.handlarborsen_store_marketplace_snapshot_v2(date, timestamptz, jsonb, jsonb,bigint) TO service_role;

-- The function is now the only writer. Without INSERT/UPDATE a direct upsert (the P1B code
-- path, or any future caller) cannot bypass the rule. SELECT stays for the report reader.
REVOKE INSERT, UPDATE ON TABLE public.handlarborsen_marketplace_snapshots FROM service_role;

commit;

begin;
-- Deliberately empty: deployment provisions neither principals nor approvals.
create table public.handlarborsen_test_data_operator_grants(
 user_id uuid not null,project_id uuid not null references public.projects(id),
 operator_binding_id uuid not null unique,
 allow_inventory boolean not null default false,
 allowed_operations text[] not null default '{}' check(allowed_operations <@ array['quarantine','restore']::text[] and cardinality(allowed_operations)<=2),
 expires_at timestamptz not null,revoked_at timestamptz,
 primary key(user_id,project_id),
 check(project_id='8f673c09-1c8f-4d78-876e-4c14bf1c89b3')
);
create table public.handlarborsen_test_data_reviews(
 package_id uuid primary key,review_ref uuid not null unique default gen_random_uuid(),
 user_id uuid not null,project_id uuid not null references public.projects(id),
 -- Immutable audit identity; live ownership is checked by every authority RPC.
 conversation_id uuid not null,
 operator_binding_id uuid not null,operation text not null check(operation in('quarantine','restore')),
 package_view jsonb not null,package_fingerprint text not null check(package_fingerprint ~ '^[0-9a-f]{64}$'),
 expires_at timestamptz not null,state text not null default 'pending' check(state in('pending','approved','rejected')),decided_at timestamptz,
 check(project_id='8f673c09-1c8f-4d78-876e-4c14bf1c89b3'),
 check((state='pending')=(decided_at is null))
);
create table public.handlarborsen_test_data_executions(
 execution_id uuid primary key default gen_random_uuid(),package_id uuid not null unique references public.handlarborsen_test_data_reviews(package_id),
 idempotency_key uuid not null unique default gen_random_uuid(),
 state text not null default 'pending' check(state in('pending','dispatching','unknown','applied','needs_new_review','not_applied')),
 claim_token uuid unique,claimed_at timestamptz,receipt jsonb,
 rejection_status text check(rejection_status in('needs_new_review','denied','disabled')),
 check((state='not_applied')=(rejection_status is not null)),
 check((state='pending')=(claim_token is null)),check((claim_token is null)=(claimed_at is null)),
 check((state in('applied','needs_new_review'))=(receipt is not null))
);
alter table public.handlarborsen_test_data_operator_grants enable row level security;
alter table public.handlarborsen_test_data_operator_grants force row level security;
alter table public.handlarborsen_test_data_reviews enable row level security;
alter table public.handlarborsen_test_data_reviews force row level security;
alter table public.handlarborsen_test_data_executions enable row level security;
alter table public.handlarborsen_test_data_executions force row level security;
revoke all on public.handlarborsen_test_data_operator_grants,public.handlarborsen_test_data_reviews,public.handlarborsen_test_data_executions from public,anon,authenticated,service_role;

create function public.handlarborsen_test_data_immutable() returns trigger language plpgsql set search_path='' as $fn$
begin
 if tg_op in('DELETE','TRUNCATE') then raise exception using errcode='42501',message='test_data_immutable';end if;
 if (to_jsonb(new)-array['state','decided_at']) is distinct from (to_jsonb(old)-array['state','decided_at'])
 or old.state<>'pending' or new.state not in('approved','rejected') or new.decided_at is null
 then raise exception using errcode='42501',message='test_data_immutable';end if;
 return new;
end $fn$;
revoke all on function public.handlarborsen_test_data_immutable() from public,anon,authenticated,service_role;
create trigger test_data_review_immutable before update or delete on public.handlarborsen_test_data_reviews for each row execute function public.handlarborsen_test_data_immutable();
create trigger test_data_review_no_truncate before truncate on public.handlarborsen_test_data_reviews for each statement execute function public.handlarborsen_test_data_immutable();

create function public.handlarborsen_resolve_test_data_operator(p_user_id uuid,p_project_id uuid,p_conversation_id uuid,p_operation text default null)
returns jsonb language plpgsql security definer set search_path='' as $fn$
declare g public.handlarborsen_test_data_operator_grants%rowtype;m text;
begin
 if p_project_id is distinct from '8f673c09-1c8f-4d78-876e-4c14bf1c89b3'::uuid
 or (p_operation is not null and p_operation not in('quarantine','restore'))
 then raise exception using errcode='42501',message='test_data_forbidden';end if;
 select atlas_mode into m from public.projects where id=p_project_id and owner_id=p_user_id and slug='handlarborsen' for share;
 if not found or m not in('observer','active') then raise exception using errcode='42501',message='test_data_forbidden';end if;
 perform 1 from public.conversations where id=p_conversation_id and user_id=p_user_id and (project_id is null or project_id=p_project_id) for share;
 if not found then raise exception using errcode='42501',message='test_data_forbidden';end if;
 select * into g from public.handlarborsen_test_data_operator_grants where user_id=p_user_id and project_id=p_project_id for share;
 if not found or not g.allow_inventory or g.revoked_at is not null or g.expires_at<=clock_timestamp()
 or (p_operation is not null and not p_operation=any(g.allowed_operations))
 then raise exception using errcode='42501',message='test_data_forbidden';end if;
 return jsonb_build_object('userId',p_user_id,'projectId',p_project_id,'conversationId',p_conversation_id,'operatorBindingId',g.operator_binding_id,'allowedOperations',g.allowed_operations,'atlasMode',m);
end $fn$;

create function public.handlarborsen_test_data_claim(p_user_id uuid,p_project_id uuid,p_conversation_id uuid,p_package_id uuid,p_claim_token uuid)
returns jsonb language plpgsql security definer set search_path='' as $fn$
declare r public.handlarborsen_test_data_reviews%rowtype;e public.handlarborsen_test_data_executions%rowtype;a jsonb;dispatch boolean:=false;
begin
 a:=public.handlarborsen_resolve_test_data_operator(p_user_id,p_project_id,p_conversation_id,null);
 select * into r from public.handlarborsen_test_data_reviews where package_id=p_package_id and user_id=p_user_id and project_id=p_project_id and conversation_id=p_conversation_id for update;
 if not found or r.state<>'approved' or r.operator_binding_id::text<>a->>'operatorBindingId' then return null;end if;
 select * into e from public.handlarborsen_test_data_executions where package_id=p_package_id for update;
 if not found then return null;end if;
 if e.state='pending' then
  perform public.handlarborsen_resolve_test_data_operator(p_user_id,p_project_id,p_conversation_id,r.operation);
  if r.expires_at<=clock_timestamp() or p_claim_token is null then return null;end if;
  update public.handlarborsen_test_data_executions set state='dispatching',claim_token=p_claim_token,claimed_at=clock_timestamp() where execution_id=e.execution_id returning * into e;
  dispatch:=true;
 end if;
 return jsonb_build_object('packageId',r.package_id,'approvalRef',r.review_ref,'executionId',e.execution_id,'idempotencyKey',e.idempotency_key,'packageView',r.package_view,'state',e.state,'dispatch',dispatch,'receipt',e.receipt)
 || case when e.rejection_status is not null then jsonb_build_object('rejectionStatus',e.rejection_status) else '{}'::jsonb end;
end $fn$;

-- A held one-use claim may acknowledge after revocation. A read-only reconciliation
-- must independently retain read authority. Neither path can start another mutation.
create function public.handlarborsen_test_data_finish(p_package_id uuid,p_execution_id uuid,p_user_id uuid,p_conversation_id uuid,p_claim_token uuid,p_receipt jsonb)
returns boolean language plpgsql security definer set search_path='' as $fn$
declare r public.handlarborsen_test_data_reviews%rowtype;e public.handlarborsen_test_data_executions%rowtype;
begin
 select * into r from public.handlarborsen_test_data_reviews where package_id=p_package_id and user_id=p_user_id and conversation_id=p_conversation_id for update;
 if not found or r.state<>'approved' then return false;end if;
 select * into e from public.handlarborsen_test_data_executions where execution_id=p_execution_id and package_id=p_package_id for update;
 if not found or e.state='pending' then return false;end if;
 if p_claim_token is null then
  perform public.handlarborsen_resolve_test_data_operator(p_user_id,r.project_id,p_conversation_id,null);
 else
  if p_claim_token is distinct from e.claim_token then return false;end if;
 end if;
 if e.receipt is not null then return p_receipt=e.receipt;end if;
 if p_receipt is null then
  if p_claim_token is null then return false;end if;
  update public.handlarborsen_test_data_executions set state='unknown' where execution_id=e.execution_id;
  return true;
 end if;
 if jsonb_typeof(p_receipt)<>'object' or (select array_agg(k order by k) from jsonb_object_keys(p_receipt) k) is distinct from array['afterSha256','beforeSha256','committedAt','counts','executionId','operation','outcome','packageId']::text[]
 or p_receipt->>'packageId' is distinct from p_package_id::text or p_receipt->>'executionId' is distinct from p_execution_id::text
 or p_receipt->>'operation' is distinct from r.operation or p_receipt->>'outcome' not in('applied','needs_new_review')
 or p_receipt->>'beforeSha256' !~ '^[a-f0-9]{64}$' or p_receipt->>'afterSha256' !~ '^[a-f0-9]{64}$'
 or p_receipt->'counts' is distinct from r.package_view->'counts'
 or ((p_receipt->>'outcome'='applied') is distinct from (p_receipt->>'committedAt' is not null))
 then return false;end if;
 update public.handlarborsen_test_data_executions set state=p_receipt->>'outcome',receipt=p_receipt where execution_id=e.execution_id;
 return true;
end $fn$;

revoke all on function public.handlarborsen_resolve_test_data_operator(uuid,uuid,uuid,text),public.handlarborsen_test_data_claim(uuid,uuid,uuid,uuid,uuid),public.handlarborsen_test_data_finish(uuid,uuid,uuid,uuid,uuid,jsonb) from public,anon,authenticated,service_role;
grant execute on function public.handlarborsen_resolve_test_data_operator(uuid,uuid,uuid,text),public.handlarborsen_test_data_claim(uuid,uuid,uuid,uuid,uuid),public.handlarborsen_test_data_finish(uuid,uuid,uuid,uuid,uuid,jsonb) to service_role;
commit;

-- Refuse to retroactively trust a producer name that existed before its server guard.
do $guard$
begin
 if not exists(select 1 from pg_catalog.pg_trigger where tgrelid='public.asset_provenance'::regclass and tgname='media_news_review_reserved_provenance')
 and exists(select 1 from public.asset_provenance where adapter_version='the-prompt-review-admission-v1')
 then raise exception 'REVIEW_ADMISSION_PREEXISTING_RECONCILIATION_REQUIRED';end if;
end $guard$;

-- The Prompt: immutable review evidence only. No dispatch/spend/schedule authority.
create table if not exists public.media_news_review_evidence (
 id uuid primary key default gen_random_uuid(),
 project_id uuid not null references public.projects(id) on delete restrict,
 post_id uuid not null, revision_id uuid not null unique, revision_sha256 text not null,
 script_id uuid not null references public.media_scripts(id) on delete restrict,
 video_asset_id uuid not null references public.assets(id) on delete restrict,
 channel text not null check(channel in ('facebook','instagram','youtube')),
 snapshot jsonb not null, snapshot_sha256 text not null check(snapshot_sha256 ~ '^[a-f0-9]{64}$'),
 root_idempotency_key text not null, request jsonb not null, created_by uuid not null, created_at timestamptz not null default now(),
 unique(project_id,root_idempotency_key,channel),
 foreign key(revision_id,post_id,project_id,revision_sha256) references public.social_content_revisions(id,post_id,project_id,sha256)
);
create index if not exists media_news_review_script_channel_idx on public.media_news_review_evidence(project_id,script_id,channel,created_at desc);
alter table public.media_news_review_evidence enable row level security;
revoke all on public.media_news_review_evidence from public,anon,authenticated,service_role;
grant select,insert on public.media_news_review_evidence to service_role;

create or replace function public.media_news_canonical_json(v jsonb) returns text
language plpgsql immutable strict security invoker set search_path='' as $fn$
begin
 case jsonb_typeof(v)
 when 'object' then return '{'||coalesce((select string_agg(to_jsonb(key)::text||':'||public.media_news_canonical_json(value),',' order by key collate "C") from jsonb_each(v)),'')||'}';
 when 'array' then return '['||coalesce((select string_agg(public.media_news_canonical_json(value),',' order by ord) from jsonb_array_elements(v) with ordinality a(value,ord)),'')||']';
 else return v::text;end case;
end $fn$;

create or replace function public.media_news_review_caption(s public.media_scripts) returns text
language sql immutable security invoker set search_path='' as $fn$
 select concat_ws(E'\n',
 nullif((select string_agg(value,E'\n' order by ord) from jsonb_array_elements_text(s.captions) with ordinality a(value,ord)),''),
 nullif((select string_agg(value,' ' order by ord) from jsonb_array_elements_text(s.hashtags) with ordinality a(value,ord)),''),
 nullif(s.cta,''))
$fn$;

-- The foundation permits owner writes. Reserve this producer identity to server admission.
create or replace function public.media_news_review_guard_provenance() returns trigger
language plpgsql security invoker set search_path='' as $fn$
begin
 if new.adapter_version='the-prompt-review-admission-v1' and current_user<>'service_role'
 then raise exception 'REVIEW_ADMISSION_SERVER_ONLY' using errcode='42501';end if;
 return new;
end $fn$;
drop trigger if exists media_news_review_reserved_provenance on public.asset_provenance;
create trigger media_news_review_reserved_provenance before insert on public.asset_provenance for each row execute function public.media_news_review_guard_provenance();

create or replace function public.media_news_snapshot_requirements(p_project uuid,s jsonb) returns text[]
language plpgsql security invoker set search_path='' as $fn$
declare r jsonb=s->'receipt';script public.media_scripts;news public.media_news_items;video public.assets;prov public.asset_provenance;
 a public.assets;ap public.asset_provenance;identity jsonb;plan public.social_launch_plan_revisions;expected jsonb;refs jsonb;used_costs jsonb;review_now timestamptz=clock_timestamp();
begin
 if jsonb_typeof(s)<>'object' or (select count(*) from jsonb_object_keys(s))<>6
 or exists(select 1 from jsonb_object_keys(s) k where k not in ('video','receipt','receiptSha256','provenanceId','planRevisionId','destinations'))
 or r->>'projectId' is distinct from p_project::text or r->>'kind' is distinct from 'the-prompt-review-render-v1'
 or r->>'language' is distinct from 'en' or r->>'creativeVersion' is distinct from 'the-prompt-illustrated-smooth-v1'
 or r->>'compositionId' is distinct from 'ThePromptIllustratedNews'
 or r->>'sourceSha' !~ '^[a-f0-9]{40}$'
 or s->>'receiptSha256' is distinct from encode(sha256(convert_to(public.media_news_canonical_json(r),'UTF8')),'hex')
 then return array['news_evidence_invalid'];end if;
 select * into video from public.assets where id=(s->'video'->>'id')::uuid and project_id=p_project;
 select * into prov from public.asset_provenance where asset_id=video.id;
 if video.id is null or video.kind<>'video' or video.status<>'active' or video.visibility<>'internal' or video.storage_bucket<>'media-assets-private'
 or video.mime_type<>'video/mp4' or video.checksum_sha256 is distinct from s->'video'->>'sha256' or video.byte_size is distinct from (s->'video'->>'byteSize')::bigint
 or r->'video' is distinct from jsonb_build_object('sha256',video.checksum_sha256,'byteSize',video.byte_size)
 or s->>'provenanceId' is distinct from video.id::text or prov.asset_id is null or prov.source<>'derived'
 or prov.adapter_version is distinct from 'the-prompt-review-admission-v1' or prov.simulated
 or prov.provider_metadata->'receipt' is distinct from r
 then return array['news_evidence_changed'];end if;
 if (r->'profile'->>'width')::int<>720 or (r->'profile'->>'height')::int<>1280 or (r->'profile'->>'fps')::int<>30
 or r->'profile'->>'videoCodec'<>'h264' or r->'profile'->>'audioCodec'<>'aac'
 or video.width<>720 or video.height<>1280 or video.duration_ms is distinct from (r->'profile'->>'durationMs')::int
 or (r->'profile'->>'frames')::int<>ceil((r->>'narrationDurationMs')::numeric*30/1000)+90
 then return array['news_evidence_invalid'];end if;
 select * into script from public.media_scripts where id=(r->>'scriptId')::uuid and project_id=p_project;
 if script.id is null or script.news_item_id is null or script.video_status='private_preview' or script.raw_output->>'private_provider_preview' is not null
 or script.news_item_id is distinct from (r->'source'->>'newsItemId')::uuid
 or encode(sha256(convert_to(coalesce(script.script,''),'UTF8')),'hex') is distinct from r->>'scriptSha256'
 or encode(sha256(convert_to(coalesce(script.hook,''),'UTF8')),'hex') is distinct from r->>'hookSha256'
 or encode(sha256(convert_to(public.media_news_review_caption(script),'UTF8')),'hex') is distinct from r->>'captionSha256'
 or script.script is distinct from r->>'transcript' or script.voice_status<>'ready'
 or script.raw_output->'pilot_voice_receipt' is distinct from r->'voiceReceipt'
 or r->'voiceReceipt'->>'voiceId' is distinct from 'qSeXEcewz7tA0Q0qk9fH'
 or r->'voiceReceipt'->>'modelId' is distinct from 'eleven_turbo_v2_5'
 or r->'voiceReceipt'->>'transcriptSha256' is distinct from r->>'scriptSha256'
 or r->'voiceReceipt'->>'audioSha256' is distinct from r->'audio'->>'sha256'
 or (r->'voiceReceipt'->>'audioByteSize')::bigint is distinct from (r->'audio'->>'byteSize')::bigint
 then return array['news_evidence_changed'];end if;
 select * into news from public.media_news_items where id=script.news_item_id and project_id=p_project;
 if (news.raw_output->>'source_published_at')::timestamptz < review_now-interval '48 hours'
 or (news.raw_output->>'source_published_at')::timestamptz > review_now+interval '15 minutes'
 then return array['news_source_expired'];end if;
 if news.id is null or news.url is distinct from r->'source'->>'url' or news.raw_output->>'source_key' is distinct from r->'source'->>'key'
 or (news.raw_output->>'source_published_at')::timestamptz is distinct from (r->'source'->>'publishedAt')::timestamptz
 then return array['news_evidence_changed'];end if;
 if jsonb_array_length(r->'images')<>3 or (select count(distinct value->>'id') from jsonb_array_elements(r->'images'))<>3
 or jsonb_array_length(r->'usage')<>3 or coalesce(r->'qa'->>'reportText','')=''
 or encode(sha256(convert_to(r->'qa'->>'reportText','UTF8')),'hex') is distinct from r->'qa'->>'reportSha256'
 or r->'qa'->>'reviewedBy' is distinct from (select owner_id::text from public.projects where id=p_project)
 or (r->'qa'->>'reviewedAt')::timestamptz>review_now
 or exists(select 1 from jsonb_array_elements(r->'usage') u where u->>'scope' is distinct from 'public_social_editorial'
 or coalesce(u->>'documentText','')='' or encode(sha256(convert_to(u->>'documentText','UTF8')),'hex') is distinct from u->>'documentSha256'
 or u->>'reviewedBy' is distinct from (select owner_id::text from public.projects where id=p_project) or (u->>'reviewedAt')::timestamptz>review_now)
 then return array['news_evidence_invalid'];end if;
 refs=(r->'images')||jsonb_build_array(r->'audio');
 if r->'assetProvenanceIds' is distinct from (select jsonb_agg(value->'id' order by ord) from jsonb_array_elements(refs) with ordinality a(value,ord))
 or to_jsonb(prov.reference_asset_ids) is distinct from r->'assetProvenanceIds' then return array['news_evidence_invalid'];end if;
 for identity in select value from jsonb_array_elements(refs) loop
  select * into a from public.assets where id=(identity->>'id')::uuid and project_id=p_project;
  select * into ap from public.asset_provenance where asset_id=a.id;
  if a.id is null or a.status<>'active' or a.visibility<>'internal' or a.storage_bucket<>'media-assets-private'
  or a.checksum_sha256 is distinct from identity->>'sha256' or a.byte_size is distinct from (identity->>'byteSize')::bigint
  or a.kind is distinct from (case when identity->>'id'=r->'audio'->>'id' then 'audio' else 'image' end)
  or ap.asset_id is null or ap.source<>'generated' or ap.simulated or ap.provider is distinct from (case when a.kind='audio' then 'elevenlabs' else 'ideogram' end)
  or a.kind='audio' and ap.model is distinct from r->'voiceReceipt'->>'modelId'
  or ap.cost_event_id is null or not (r->'costEventIds' ? ap.cost_event_id::text)
  or not exists(select 1 from public.cost_events c where c.id=ap.cost_event_id and c.project_id=p_project and c.provider=ap.provider)
  then return array['news_evidence_changed'];end if;
 end loop;
 select jsonb_agg(c order by c) into used_costs from (select distinct cost_prov.cost_event_id::text c from public.asset_provenance cost_prov where cost_prov.asset_id in (select (value->>'id')::uuid from jsonb_array_elements(refs))) x;
 if used_costs is distinct from (select jsonb_agg(value order by value) from jsonb_array_elements(r->'costEventIds'))
 then return array['news_evidence_invalid'];end if;
 select pr.* into plan from public.social_launch_plans p join public.social_launch_plan_revisions pr on pr.id=p.current_revision_id and pr.project_id=p.project_id
 where p.project_id=p_project and p.current_revision_id=(s->>'planRevisionId')::uuid;
 if plan.id is null or not exists(select 1 from public.social_launch_plan_decisions d where d.project_id=p_project and d.revision_id=plan.id and d.sha256=plan.sha256 and d.decision='approve')
 then return array['news_evidence_changed'];end if;
 select coalesce(jsonb_agg(jsonb_build_object('channel',c->>'channel','bindingId',b.binding_id,'accountId',b.external_account_id) order by c->>'channel'),'[]') into expected
 from jsonb_array_elements(plan.choices) c left join public.social_account_bindings b on b.project_id=p_project and b.platform=c->>'channel' and b.superseded_at is null
 where c->>'format'='video' and c->>'channel' in ('facebook','instagram','youtube');
 if expected='[]'::jsonb or expected is distinct from s->'destinations'
 or exists(select 1 from public.social_account_bindings where project_id=p_project and superseded_at is null and blocked_at is not null and platform in (select value->>'channel' from jsonb_array_elements(expected)))
 then return array['news_evidence_changed'];end if;
 if exists(select 1 from public.projects where id=p_project and execution_paused)
 or exists(select 1 from public.project_lifecycle where project_id=p_project and state<>'active')
 or exists(select 1 from public.platform_config where automation_paused) then return array['news_project_stopped'];end if;
 return array[]::text[];
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow or numeric_value_out_of_range then return array['news_evidence_invalid'];
end $fn$;

create or replace function public.media_news_review_requirements(p_revision uuid) returns text[]
language plpgsql security invoker set search_path='' as $fn$
declare r public.social_content_revisions;e public.media_news_review_evidence;receipt jsonb;reasons text[];
begin
 select * into strict r from public.social_content_revisions where id=p_revision;
 select * into e from public.media_news_review_evidence where revision_id=r.id and project_id=r.project_id;
 if e.id is null then
  if exists(select 1 from public.media_news_review_evidence where post_id=r.post_id and project_id=r.project_id)
  or exists(select 1 from jsonb_array_elements(r.media) m join public.asset_provenance ap on ap.asset_id=(m->>'id')::uuid where ap.adapter_version='the-prompt-review-admission-v1')
  then return array['news_evidence_required'];end if;return array[]::text[];
 end if;
 receipt=e.snapshot->'receipt';
 if e.snapshot_sha256 is distinct from encode(sha256(convert_to(public.media_news_canonical_json(e.snapshot),'UTF8')),'hex')
 or r.draft->>'format'<>'video' or r.draft->>'channel' is distinct from e.channel or r.draft->'mediaIds' is distinct from jsonb_build_array(e.video_asset_id)
 or r.draft->>'title' is distinct from (select hook from public.media_scripts where id=e.script_id and project_id=r.project_id)
 or r.draft->>'text' is distinct from (select public.media_news_review_caption(s) from public.media_scripts s where id=e.script_id and project_id=r.project_id)
 or r.draft->>'linkUrl' is distinct from receipt->'source'->>'url'
 then return array['news_evidence_changed'];end if;
 return public.media_news_snapshot_requirements(r.project_id,e.snapshot);
end $fn$;

create or replace function public.media_news_review_guard_evidence() returns trigger
language plpgsql security invoker set search_path='' as $fn$
declare r public.social_content_revisions;
begin
 perform 1 from public.projects where id=new.project_id for update;
 perform 1 from public.social_content_posts where id=new.post_id and project_id=new.project_id and current_revision_id=new.revision_id for update;
 if not found then raise exception 'SOCIAL_CONTENT_REVISION_CONFLICT';end if;
 if exists(select 1 from public.social_content_decisions where revision_id=new.revision_id) then raise exception 'SOCIAL_CONTENT_REVIEW_REQUIRED';end if;
 select * into r from public.social_content_revisions where id=new.revision_id and post_id=new.post_id and project_id=new.project_id and sha256=new.revision_sha256;
 if r.id is null or new.script_id::text is distinct from new.snapshot->'receipt'->>'scriptId' or new.video_asset_id::text is distinct from new.snapshot->'video'->>'id'
 or new.snapshot_sha256 is distinct from encode(sha256(convert_to(public.media_news_canonical_json(new.snapshot),'UTF8')),'hex')
 or cardinality(public.media_news_snapshot_requirements(new.project_id,new.snapshot))<>0
 then raise exception 'SOCIAL_CONTENT_REVIEW_REQUIRED';end if;
 return new;
end $fn$;
drop trigger if exists media_news_review_insert_guard on public.media_news_review_evidence;
create trigger media_news_review_insert_guard before insert on public.media_news_review_evidence for each row execute function public.media_news_review_guard_evidence();
create or replace function public.media_news_review_reject_mutation() returns trigger language plpgsql security invoker set search_path='' as $fn$
begin raise exception 'media_news_review_evidence is append-only' using errcode='23001';end $fn$;
drop trigger if exists media_news_review_no_mutation on public.media_news_review_evidence;
create trigger media_news_review_no_mutation before update or delete on public.media_news_review_evidence for each row execute function public.media_news_review_reject_mutation();
drop trigger if exists media_news_review_no_truncate on public.media_news_review_evidence;
create trigger media_news_review_no_truncate before truncate on public.media_news_review_evidence for each statement execute function public.media_news_review_reject_mutation();

create or replace function public.media_news_review_read(p_principal jsonb,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path='' as $fn$
declare project uuid=(p_input->>'projectId')::uuid;post uuid=(p_input->>'postId')::uuid;r public.social_content_revisions;e public.media_news_review_evidence;reasons text[];pub text[]=array['video_transport_unavailable','release_authority_missing','schedule_not_activated'];receipt jsonb;
begin
 perform public.social_launch_assert_owner(p_principal,jsonb_build_object('projectId',project));
 if (select count(*) from jsonb_object_keys(p_input))<>2 or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('projectId','postId')) then raise exception 'NEWS_REVIEW_INVALID_BODY';end if;
 select rv.* into r from public.social_content_posts p join public.social_content_revisions rv on rv.id=p.current_revision_id and rv.project_id=p.project_id and rv.post_id=p.id where p.project_id=project and p.id=post;
 if r.id is null then raise exception 'NEWS_REVIEW_NOT_FOUND' using errcode='P0002';end if;
 select * into e from public.media_news_review_evidence where revision_id=r.id and project_id=project;
 reasons=public.media_news_review_requirements(r.id);
 if e.id is null and cardinality(reasons)=0 then reasons=array['news_evidence_required'];end if;
 if not exists(select 1 from public.social_content_decisions where revision_id=r.id and sha256=r.sha256 and decision='approve') then pub=array_append(pub,'review_required');end if;
 if r.binding_id is null then pub=array_append(pub,'account_required');end if;
 pub=pub||public.social_content_requirements(r.id);
 receipt=e.snapshot->'receipt';
 return jsonb_build_object('projectId',project,'postId',post,'revisionId',r.id,'evidenceSha256',e.snapshot_sha256,
 'review_packet_ready',e.id is not null and cardinality(reasons)=0,'blockers',to_jsonb(reasons),'publicationBlockers',to_jsonb(pub),'canPublish',false,'dispatchEnabled',false,
 'source',case when e.id is null then null else receipt->'source' end,'creativeVersion',receipt->>'creativeVersion',
 'video',e.snapshot->'video','imageCount',3,'voiceLabel','Victoria','aiDisclosure','AI-GENERATED / EDITORIAL ILLUSTRATIONS');
end $fn$;

-- Call only while holding projects FOR UPDATE. Its FK conflict with KEY SHARE also
-- serializes insertion of a previously absent binding/plan/lifecycle row.
create or replace function public.media_news_review_lock_inputs(p_project uuid,s jsonb) returns void
language plpgsql security invoker set search_path='' as $fn$
begin
 perform 1 from public.media_scripts where id=(s->'receipt'->>'scriptId')::uuid and project_id=p_project for update;
 perform 1 from public.media_news_items where id=(s->'receipt'->'source'->>'newsItemId')::uuid and project_id=p_project for update;
 perform 1 from public.assets where project_id=p_project and id in (select (value->>'id')::uuid from jsonb_array_elements((s->'receipt'->'images')||jsonb_build_array(s->'receipt'->'audio',s->'video'))) order by id for update;
 perform 1 from public.asset_provenance where asset_id in (select (value->>'id')::uuid from jsonb_array_elements((s->'receipt'->'images')||jsonb_build_array(s->'receipt'->'audio',s->'video'))) order by asset_id for share;
 perform 1 from public.cost_events where project_id=p_project and id in (select value::uuid from jsonb_array_elements_text(s->'receipt'->'costEventIds')) order by id for share;
 perform 1 from public.social_account_bindings where project_id=p_project and superseded_at is null order by binding_id for share;
 perform 1 from public.social_launch_plans where project_id=p_project for update;
 -- Lifecycle writes already require projects FOR UPDATE through project_lifecycle_change.
 perform 1 from public.platform_config order by id for share;
end $fn$;

create or replace function public.media_news_review_prepare(p_principal jsonb,p_input jsonb,p_snapshot jsonb) returns jsonb
language plpgsql security invoker set search_path='' as $fn$
declare project uuid=(p_input->>'projectId')::uuid;actor uuid=(p_principal->>'userId')::uuid;v_script_id uuid=(p_input->>'scriptId')::uuid;video uuid=(p_input->>'videoAssetId')::uuid;
 previous public.media_news_review_evidence;revision public.social_content_revisions;post uuid;expected uuid;destination jsonb;draft jsonb;body jsonb;result jsonb='[]';fingerprint text;reasons text[];channel text;caption text;title text;
begin
 perform public.social_launch_assert_owner(p_principal,jsonb_build_object('projectId',project));
 if (select count(*) from jsonb_object_keys(p_input))<>4 or exists(select 1 from jsonb_object_keys(p_input) k where k not in ('projectId','scriptId','videoAssetId','idempotencyKey'))
 or coalesce(p_input->>'idempotencyKey','') !~ '^[A-Za-z0-9_-]{1,100}$'
 or p_snapshot->'receipt'->>'projectId' is distinct from project::text or p_snapshot->'receipt'->>'scriptId' is distinct from v_script_id::text
 or p_snapshot->'video'->>'id' is distinct from video::text then raise exception 'NEWS_REVIEW_INVALID_BODY';end if;
 perform 1 from public.projects where id=project for update;perform public.social_launch_assert_owner(p_principal,jsonb_build_object('projectId',project));perform public.social_content_active(project);
 perform public.media_news_review_lock_inputs(project,p_snapshot);
 fingerprint=encode(sha256(convert_to(public.media_news_canonical_json(p_snapshot),'UTF8')),'hex');
 select e.* into previous from public.media_news_review_evidence e where e.project_id=project and e.root_idempotency_key=p_input->>'idempotencyKey' order by e.channel limit 1;
 if previous.id is not null and (previous.request is distinct from p_input or previous.snapshot_sha256 is distinct from fingerprint or previous.created_by<>actor) then raise exception 'NEWS_REVIEW_REVISION_CONFLICT';end if;
 reasons=public.media_news_snapshot_requirements(project,p_snapshot);
 if cardinality(reasons)>0 then
 if previous.id is not null then raise exception 'NEWS_REVIEW_REVISION_CONFLICT';end if;
 raise exception 'NEWS_REVIEW_REVIEW_REQUIRED: %',reasons;end if;
 for destination in select value from jsonb_array_elements(p_snapshot->'destinations') loop
  channel=destination->>'channel';
  select * into previous from public.media_news_review_evidence where project_id=project and root_idempotency_key=p_input->>'idempotencyKey' and media_news_review_evidence.channel=destination->>'channel';
  if previous.id is not null then
   if not exists(select 1 from public.social_content_posts where id=previous.post_id and project_id=project and current_revision_id=previous.revision_id) then raise exception 'NEWS_REVIEW_REVISION_CONFLICT';end if;
   post=previous.post_id;
  else
   select e.post_id into post from public.media_news_review_evidence e where e.project_id=project and e.script_id=v_script_id and e.channel=destination->>'channel' order by e.created_at desc,e.id limit 1;
   expected=null;
   if post is null then post=gen_random_uuid();else select current_revision_id into expected from public.social_content_posts where id=post and project_id=project for update;end if;
   select s.hook,public.media_news_review_caption(s) into title,caption from public.media_scripts s where s.id=v_script_id and s.project_id=project;
   draft=jsonb_build_object('channel',channel,'format','video','title',title,'text',caption,'linkUrl',p_snapshot->'receipt'->'source'->>'url','mediaIds',jsonb_build_array(video),'mediaBrief','AI editorial illustrations','scheduledAt',null);
   body=jsonb_build_object('projectId',project,'postId',post,'expectedRevisionId',expected,'planRevisionId',p_snapshot->>'planRevisionId','idempotencyKey',encode(sha256(convert_to(p_input->>'idempotencyKey'||':'||channel,'UTF8')),'hex'),'draft',draft);
   perform public.social_content_save(p_principal,body);
   select rv.* into revision from public.social_content_posts p join public.social_content_revisions rv on rv.id=p.current_revision_id and rv.post_id=p.id and rv.project_id=p.project_id where p.id=post and p.project_id=project;
   insert into public.media_news_review_evidence(project_id,post_id,revision_id,revision_sha256,script_id,video_asset_id,channel,snapshot,snapshot_sha256,root_idempotency_key,request,created_by)
   values(project,post,revision.id,revision.sha256,v_script_id,video,channel,p_snapshot,fingerprint,p_input->>'idempotencyKey',p_input,actor);
  end if;
  result=result||jsonb_build_array(public.media_news_review_read(p_principal,jsonb_build_object('projectId',project,'postId',post)));
 end loop;
 return result;
end $fn$;

revoke all on function public.media_news_review_lock_inputs(uuid,jsonb),public.media_news_canonical_json(jsonb),public.media_news_review_caption(public.media_scripts),public.media_news_review_guard_provenance(),public.media_news_snapshot_requirements(uuid,jsonb),public.media_news_review_requirements(uuid),public.media_news_review_guard_evidence(),public.media_news_review_reject_mutation(),public.media_news_review_read(jsonb,jsonb),public.media_news_review_prepare(jsonb,jsonb,jsonb) from public,anon,authenticated;
grant execute on function public.media_news_review_lock_inputs(uuid,jsonb),public.media_news_canonical_json(jsonb),public.media_news_review_caption(public.media_scripts),public.media_news_review_guard_provenance(),public.media_news_snapshot_requirements(uuid,jsonb),public.media_news_review_requirements(uuid),public.media_news_review_guard_evidence(),public.media_news_review_reject_mutation(),public.media_news_review_read(jsonb,jsonb),public.media_news_review_prepare(jsonb,jsonb,jsonb) to service_role;
comment on table public.media_news_review_evidence is 'Immutable source/voice/usage/render evidence bound to exact social content revision. Grants no publication, scheduling or spend authority.';


create or replace function public.social_content_requirements(p_revision uuid) returns text[] language plpgsql security invoker set search_path='' as $fn$
declare r public.social_content_revisions; reasons text[]=array['activation_required']; active_binding uuid; blocked timestamptz;
begin
 select * into strict r from public.social_content_revisions where id=p_revision;
 if not exists(select 1 from public.social_launch_plans p join public.social_launch_plan_revisions pr on pr.id=p.current_revision_id and pr.project_id=p.project_id
 join public.social_launch_plan_decisions d on d.project_id=pr.project_id and d.revision_id=pr.id and d.sha256=pr.sha256 and d.decision='approve'
 where p.project_id=r.project_id and p.current_revision_id=r.plan_revision_id) then reasons=array_append(reasons,'plan_changed'); end if;
 select binding_id,blocked_at into active_binding,blocked from public.social_account_bindings where project_id=r.project_id and platform=r.draft->>'channel' and superseded_at is null;
 if active_binding is distinct from r.binding_id or blocked is not null then reasons=array_append(reasons,'destination_changed');elsif active_binding is null then reasons=array_append(reasons,'account_required');end if;
 if r.draft->>'format' in ('image','video') and jsonb_array_length(r.media)=0 then reasons=array_append(reasons,'media_required');end if;
 if exists(select 1 from jsonb_array_elements(r.media) m where not exists(select 1 from public.assets a where a.id=(m->>'id')::uuid and a.project_id=r.project_id and a.status='active' and a.checksum_sha256=m->>'sha256' and a.kind=m->>'kind' and a.mime_type=m->>'mimeType')) then reasons=array_append(reasons,'media_changed');end if;
 if r.draft->>'scheduledAt' is not null and (r.draft->>'scheduledAt')::timestamptz<=now() then reasons=array_append(reasons,'time_passed');end if;
 return reasons || public.media_news_review_requirements(p_revision);
end $fn$;

create or replace function public.social_content_read(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare p public.projects; result jsonb; asset_list jsonb; plan_id uuid; approved boolean;
begin
 perform public.social_launch_assert_owner(p_principal,p_input);
 if exists(select 1 from jsonb_object_keys(p_input) k where k not in ('projectId','conversationId')) then raise exception 'SOCIAL_CONTENT_INVALID_BODY';end if;
 select * into strict p from public.projects where id=(p_input->>'projectId')::uuid;
 select current_revision_id into plan_id from public.social_launch_plans where project_id=p.id;
 approved=exists(select 1 from public.social_launch_plan_decisions where project_id=p.id and revision_id=plan_id and decision='approve');
 select coalesce(jsonb_agg(entry order by created_at desc),'[]') into result from (
 select posts.created_at,jsonb_build_object('id',posts.id,'revision',jsonb_build_object('id',r.id,'sequence',r.sequence,'sha256',r.sha256,'planRevisionId',r.plan_revision_id,'draft',r.draft,'media',r.media,'binding',r.binding,'createdAt',r.created_at),
 'decision',case when d.id is null then null else jsonb_build_object('id',d.id,'decision',d.decision,'revisionId',d.revision_id,'sha256',d.sha256,'decidedAt',d.decided_at) end,
 'status',case when reasons && array['plan_changed','destination_changed','media_changed','time_passed','news_evidence_required','news_evidence_invalid','news_evidence_changed','news_source_expired','news_project_stopped'] then 'needs_review' when d.decision='approve' then 'approved' when d.decision='reject' then 'rejected' else 'proposal' end,'requirements',to_jsonb(reasons)) || case when exists(select 1 from public.media_news_review_evidence e where e.project_id=posts.project_id and e.post_id=posts.id)
 or exists(select 1 from jsonb_array_elements(r.media) m join public.asset_provenance ap on ap.asset_id=(m->>'id')::uuid where ap.adapter_version='the-prompt-review-admission-v1')
 then jsonb_build_object('newsReview',public.media_news_review_read(p_principal,jsonb_build_object('projectId',p.id,'postId',posts.id))) else '{}'::jsonb end entry
 from public.social_content_posts posts join public.social_content_revisions r on r.id=posts.current_revision_id and r.project_id=posts.project_id and r.post_id=posts.id
 left join public.social_content_decisions d on d.revision_id=r.id cross join lateral (select public.social_content_requirements(r.id) reasons) checks where posts.project_id=p.id) entries;
 select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'kind',a.kind,'sha256',a.checksum_sha256,'mimeType',a.mime_type,'width',a.width,'height',a.height)),'[]') into asset_list
 from (select * from public.assets where project_id=p.id and status='active' and kind in ('image','video') and mime_type in ('image/png','image/jpeg','image/webp','image/gif','image/avif','video/mp4','video/webm') order by created_at desc,id limit 100) a;
 return jsonb_build_object('project',jsonb_build_object('id',p.id,'name',p.name,'slug',p.slug),'posts',result,'assets',asset_list,'hasMoreAssets',(select count(*)>100 from public.assets where project_id=p.id and status='active' and kind in ('image','video')),
 'plannedChannels',coalesce((select choices from public.social_launch_plan_revisions where id=plan_id),'[]'::jsonb),'currentPlanRevisionId',plan_id,'planApproved',approved,'workspaceUrl','/projects/'||p.slug||'/social#content','dispatchEnabled',false,'publicationReady',false);
end $fn$;

create or replace function public.social_content_decide(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare project uuid=(p_input->>'projectId')::uuid;actor uuid=(p_principal->>'userId')::uuid;r public.social_content_revisions;d public.social_content_decisions;reasons text[];news_snapshot jsonb;
begin
 perform public.social_launch_assert_owner(p_principal,p_input);
 if exists(select 1 from jsonb_object_keys(p_input) k where k not in ('projectId','postId','revisionId','sha256','decision','idempotencyKey'))
 or coalesce(p_input->>'decision','') not in ('approve','reject') or coalesce(p_input->>'sha256','') !~ '^[a-f0-9]{64}$' or coalesce(p_input->>'idempotencyKey','') !~ '^[A-Za-z0-9_-]{1,100}$' then raise exception 'SOCIAL_CONTENT_INVALID_BODY';end if;
 perform 1 from public.projects where id=project for update;perform public.social_launch_assert_owner(p_principal,p_input);perform public.social_content_active(project);
 select * into d from public.social_content_decisions where project_id=project and idempotency_key=p_input->>'idempotencyKey';
 if d.id is not null then
 if d.post_id is distinct from (p_input->>'postId')::uuid or d.revision_id is distinct from (p_input->>'revisionId')::uuid or d.sha256 is distinct from p_input->>'sha256' or d.decision is distinct from p_input->>'decision' or d.decided_by<>actor then raise exception 'SOCIAL_CONTENT_REVISION_CONFLICT';end if;
 return public.social_content_read(p_principal,jsonb_build_object('projectId',project));end if;
 select r0.* into r from public.social_content_posts p join public.social_content_revisions r0 on r0.id=p.current_revision_id and r0.post_id=p.id and r0.project_id=p.project_id where p.id=(p_input->>'postId')::uuid and p.project_id=project for update of p;
 if r.id is null or r.id is distinct from (p_input->>'revisionId')::uuid or r.sha256 is distinct from p_input->>'sha256' then raise exception 'SOCIAL_CONTENT_REVISION_CONFLICT';end if;
 if p_input->>'decision'='approve' then
 select snapshot into news_snapshot from public.media_news_review_evidence where revision_id=r.id and project_id=project;
 if news_snapshot is not null then perform public.media_news_review_lock_inputs(project,news_snapshot);perform public.social_content_active(project);end if;
 reasons=public.social_content_requirements(r.id);if 'media_required'=any(reasons) then raise exception 'SOCIAL_CONTENT_MEDIA_REQUIRED';end if;
 if reasons && array['plan_changed','destination_changed','media_changed','time_passed','news_evidence_required','news_evidence_invalid','news_evidence_changed','news_source_expired','news_project_stopped'] then raise exception 'SOCIAL_CONTENT_REVIEW_REQUIRED';end if;end if;
 select * into d from public.social_content_decisions where revision_id=r.id;
 if d.id is not null then
 if d.decision is distinct from p_input->>'decision' or d.decided_by<>actor then raise exception 'SOCIAL_CONTENT_REVISION_CONFLICT';end if;
 else insert into public.social_content_decisions(project_id,post_id,revision_id,sha256,decision,idempotency_key,decided_by) values(project,r.post_id,r.id,r.sha256,p_input->>'decision',p_input->>'idempotencyKey',actor);end if;
 return public.social_content_read(p_principal,jsonb_build_object('projectId',project));
end $fn$;

-- Reviewed metadata and preparation checks only. No sender or scheduler changes.
create table public.sales_contact_timing_rules(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),owner_id uuid not null,
 version integer not null check(version>0),previous_id uuid,request_key uuid not null,request jsonb not null,
 min_wait_seconds integer not null check(min_wait_seconds>=1209600),max_reminders integer not null check(max_reminders between 0 and 1),
 max_source_age_seconds integer not null check(max_source_age_seconds between 1 and 900),created_at timestamptz not null default clock_timestamp(),
 unique(project_id,id),unique(project_id,version),unique(project_id,request_key),
 foreign key(project_id,previous_id) references public.sales_contact_timing_rules(project_id,id),check((version=1)=(previous_id is null))
);
create table public.sales_contact_history_revisions(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id),owner_id uuid not null,recipient text not null,
 version integer not null check(version>0),previous_id uuid,request_key uuid not null,request jsonb not null,data jsonb not null,source_context jsonb not null,
 created_at timestamptz not null default clock_timestamp(),unique(project_id,id),unique(project_id,recipient,version),unique(project_id,request_key),
 foreign key(project_id,previous_id) references public.sales_contact_history_revisions(project_id,id),check((version=1)=(previous_id is null)),
 check(recipient=lower(btrim(recipient)) and recipient !~ E'[\\r\\n]' and length(recipient) between 3 and 254)
);
alter table public.sales_contact_timing_rules enable row level security;
alter table public.sales_contact_history_revisions enable row level security;
revoke all on public.sales_contact_timing_rules,public.sales_contact_history_revisions from public,anon,authenticated,service_role;
grant select,insert on public.sales_contact_timing_rules,public.sales_contact_history_revisions to service_role;
create trigger sales_timing_rules_immutable before update or delete on public.sales_contact_timing_rules for each row execute function public.sales_immutable();
create trigger sales_timing_history_immutable before update or delete on public.sales_contact_history_revisions for each row execute function public.sales_immutable();

create function public.sales_timing_fields(v jsonb,keys text[]) returns void language plpgsql security invoker set search_path='' as $$
begin
 if jsonb_typeof(v) is distinct from 'object' then raise exception 'INVALID_BODY' using errcode='22023';end if;
 if not(v ?& keys) or exists(select from jsonb_object_keys(v) k where not(k=any(keys))) then raise exception 'INVALID_BODY' using errcode='22023';end if;
end$$;
create function public.sales_timing_uuid(v jsonb) returns uuid language plpgsql security invoker set search_path='' as $$
begin
 if jsonb_typeof(v) is distinct from 'string' or v#>>'{}' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then raise exception 'INVALID_BODY' using errcode='22023';end if;
 return (v#>>'{}')::uuid;
end$$;
create function public.sales_timing_text(v jsonb) returns text language plpgsql security invoker set search_path='' as $$
declare s text:=v#>>'{}';begin
 if jsonb_typeof(v) is distinct from 'string' or length(btrim(s)) not between 1 and 500 or s ~ E'[\\r\\n\\x01]' then raise exception 'INVALID_BODY' using errcode='22023';end if;return s;
end$$;
create function public.sales_timing_instant(v jsonb,at timestamptz) returns timestamptz language plpgsql security invoker set search_path='' as $$
declare s text:=v#>>'{}';t timestamptz;begin
 if jsonb_typeof(v) is distinct from 'string' or s !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T([01][0-9]|2[0-3]):[0-5][0-9]:[0-5][0-9](\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$' then raise exception 'INVALID_BODY' using errcode='22023';end if;
 t:=s::timestamptz;if not isfinite(t) or t>at then raise exception 'INVALID_BODY' using errcode='22023';end if;return t;
exception when invalid_datetime_format or datetime_field_overflow or invalid_time_zone_displacement_value then raise exception 'INVALID_BODY' using errcode='22023';
end$$;
create function public.sales_timing_context(pid uuid,address text) returns jsonb language sql stable security invoker set search_path='' as $$
 select jsonb_build_object('mailboxes',coalesce((select jsonb_agg(jsonb_build_array(b.id,b.generation,b.email,b.status,c.version,c.epoch,c.since_at,c.selected_contact_ids) order by b.id) from public.sales_mailbox_connections b left join public.sales_inbox_configs c on c.mailbox_id=b.id where b.project_id=pid),'[]'::jsonb),
 'inbox',coalesce((select jsonb_agg(jsonb_build_array(m.id,m.version,m.mailbox_id,m.internal_date) order by m.id) from public.sales_inbox_messages m where m.project_id=pid and lower(btrim(coalesce(substring(m.header->>'from' from '<([^<>]+)>'),m.header->>'from')))=address),'[]'::jsonb))
$$;
create function public.sales_timing_validate_history(d jsonb,at timestamptz) returns void language plpgsql security invoker set search_path='' as $$
declare s jsonb;e jsonb;p jsonb;x jsonb;t jsonb;sid text;since_at timestamptz;through_at timestamptz;occurred timestamptz;begin
 perform public.sales_timing_fields(d,array['schemaVersion','contactVersions','history','olderHistoryAttestation','sources','events','correctionOf','reviewNote']);
 if d->'schemaVersion' is distinct from '1'::jsonb or coalesce(d->>'history','') not in('unknown','owner_confirmed_none','contacted') then raise exception 'INVALID_BODY' using errcode='22023';end if;
 perform public.sales_timing_text(d->'reviewNote');
 if d->'olderHistoryAttestation'<>'null' then perform public.sales_timing_text(d->'olderHistoryAttestation');end if;
 if d->>'history'='owner_confirmed_none' and d->'olderHistoryAttestation'='null' then raise exception 'INVALID_BODY' using errcode='22023';end if;
 if d->'correctionOf'<>'null' then perform public.sales_timing_uuid(d->'correctionOf');end if;
 if jsonb_typeof(d->'contactVersions')<>'array' or jsonb_array_length(d->'contactVersions') not between 1 and 16 or jsonb_typeof(d->'sources')<>'array' or jsonb_array_length(d->'sources')>8 or jsonb_typeof(d->'events')<>'array' or jsonb_array_length(d->'events')>100 then raise exception 'INVALID_BODY' using errcode='22023';end if;
 for x in select value from jsonb_array_elements(d->'contactVersions') loop
  perform public.sales_timing_fields(x,array['id','version']);perform public.sales_timing_uuid(x->'id');
  if jsonb_typeof(x->'version')<>'number' or x->>'version' !~ '^[1-9][0-9]{0,8}$' then raise exception 'INVALID_BODY' using errcode='22023';end if;
 end loop;
 if (select count(*)<>count(distinct q->>'id') from jsonb_array_elements(d->'contactVersions') q) then raise exception 'INVALID_BODY' using errcode='22023';end if;
 for s in select value from jsonb_array_elements(d->'sources') loop
  perform public.sales_timing_fields(s,array['sourceKey','channel','identityRef','scopeRef','since','through','observedAt','state','reference']);
  foreach sid in array array['sourceKey','identityRef','scopeRef','reference'] loop perform public.sales_timing_text(s->sid);end loop;
  if coalesce(s->>'channel','') not in('strato_sent','strato_inbox','resend','operator') or coalesce(s->>'state','') not in('complete','gap','failed') then raise exception 'INVALID_BODY' using errcode='22023';end if;
  since_at:=public.sales_timing_instant(s->'since',at);through_at:=public.sales_timing_instant(s->'through',at);
  if since_at>through_at or through_at>public.sales_timing_instant(s->'observedAt',at) then raise exception 'INVALID_BODY' using errcode='22023';end if;
 end loop;
 if (select count(*)<>count(distinct q->>'sourceKey') from jsonb_array_elements(d->'sources') q) then raise exception 'INVALID_BODY' using errcode='22023';end if;
 for e in select value from jsonb_array_elements(d->'events') loop
  perform public.sales_timing_fields(e,array['id','sourceRefs','providerRefs','occurredAt','direction','outcome','kind','invitationId','inReplyToEventId','reviewedDuplicateOf']);
  perform public.sales_timing_uuid(e->'id');occurred:=public.sales_timing_instant(e->'occurredAt',at);
  foreach sid in array array['invitationId','inReplyToEventId','reviewedDuplicateOf'] loop if e->sid<>'null' then perform public.sales_timing_uuid(e->sid);end if;end loop;
  if coalesce(e->>'direction','') not in('outbound','inbound') or coalesce(e->>'outcome','') not in('accepted','delivery_unknown','failed_before_send','received','bounced','unsubscribed') or coalesce(e->>'kind','') not in('initial','reminder','requested_reply','unclassified')
  or ((e->>'direction'='outbound') is distinct from (e->>'outcome' in('accepted','delivery_unknown','failed_before_send'))) then raise exception 'INVALID_BODY' using errcode='22023';end if;
  if jsonb_typeof(e->'sourceRefs')<>'array' or jsonb_array_length(e->'sourceRefs') not between 1 and 8 or jsonb_typeof(e->'providerRefs')<>'array' or jsonb_array_length(e->'providerRefs') not between 1 and 8 then raise exception 'INVALID_BODY' using errcode='22023';end if;
  for x in select value from jsonb_array_elements(e->'sourceRefs') loop
   sid:=public.sales_timing_text(x);select value into s from jsonb_array_elements(d->'sources') where value->>'sourceKey'=sid;
   if not found or occurred<(s->>'since')::timestamptz or occurred>(s->>'through')::timestamptz then raise exception 'INVALID_BODY' using errcode='22023';end if;
  end loop;
  if (select count(*)<>count(distinct value) from jsonb_array_elements(e->'sourceRefs')) then raise exception 'INVALID_BODY' using errcode='22023';end if;
  for p in select value from jsonb_array_elements(e->'providerRefs') loop
   perform public.sales_timing_fields(p,array['sourceKey','id']);perform public.sales_timing_text(p->'id');
   if not(e->'sourceRefs' ? public.sales_timing_text(p->'sourceKey')) then raise exception 'INVALID_BODY' using errcode='22023';end if;
  end loop;
  if (select count(*)<>count(distinct value) from jsonb_array_elements(e->'providerRefs')) then raise exception 'INVALID_BODY' using errcode='22023';end if;
  if e->'reviewedDuplicateOf'<>'null' then
   select value into t from jsonb_array_elements(d->'events') where value->>'id'=e->>'reviewedDuplicateOf';
   if not found or t->>'id'=e->>'id' or t->'reviewedDuplicateOf'<>'null' or (t-array['id','sourceRefs','providerRefs','reviewedDuplicateOf']) is distinct from (e-array['id','sourceRefs','providerRefs','reviewedDuplicateOf']) then raise exception 'INVALID_BODY' using errcode='22023';end if;
  end if;
 end loop;
 if (select count(*)<>count(distinct q->>'id') from jsonb_array_elements(d->'events') q) then raise exception 'INVALID_BODY' using errcode='22023';end if;
end$$;
create function public.sales_timing_rules_json(r public.sales_contact_timing_rules) returns jsonb language sql stable security invoker set search_path='' as $$
 select jsonb_build_object('id',r.id,'projectId',r.project_id,'version',r.version,'previousId',r.previous_id,'minWaitSeconds',r.min_wait_seconds,'maxReminders',r.max_reminders,'maxSourceAgeSeconds',r.max_source_age_seconds,'reviewedBy',r.owner_id,'createdAt',r.created_at)
$$;
create function public.sales_timing_history_json(h public.sales_contact_history_revisions) returns jsonb language sql stable security invoker set search_path='' as $$
 select jsonb_build_object('id',h.id,'projectId',h.project_id,'recipient',h.recipient,'version',h.version,'previousId',h.previous_id,'data',h.data,'reviewedBy',h.owner_id,'createdAt',h.created_at)
$$;
create function public.sales_timing_save_rules(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare pid uuid;r public.sales_contact_timing_rules;old public.sales_contact_timing_rules;begin
 pid:=public.sales_timing_uuid(p_input->'projectId');perform public.sales_owner(p_principal,pid);
 perform public.sales_timing_fields(p_input,array['projectId','idempotencyKey','expectedPreviousId','minWaitSeconds','maxReminders','maxSourceAgeSeconds','confirmed']);
 perform public.sales_timing_uuid(p_input->'idempotencyKey');
 if p_input->'expectedPreviousId'<>'null' then perform public.sales_timing_uuid(p_input->'expectedPreviousId');end if;
 if p_input->'confirmed' is distinct from 'true'::jsonb or jsonb_typeof(p_input->'minWaitSeconds')<>'number' or p_input->>'minWaitSeconds' !~ '^[1-9][0-9]{0,9}$' or (p_input->>'minWaitSeconds')::bigint not between 1209600 and 2147483647 or p_input->'maxReminders' not in('0'::jsonb,'1'::jsonb) or jsonb_typeof(p_input->'maxSourceAgeSeconds')<>'number' or p_input->>'maxSourceAgeSeconds' !~ '^[1-9][0-9]{0,2}$' or (p_input->>'maxSourceAgeSeconds')::integer>900 then raise exception 'INVALID_BODY' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(pid::text||':sales-contact-eligibility',0));
 select * into r from public.sales_contact_timing_rules where project_id=pid and request_key=(p_input->>'idempotencyKey')::uuid;
 if found then if r.request is distinct from p_input then raise exception 'REVISION_CONFLICT' using errcode='23505';end if;return public.sales_timing_rules_json(r);end if;
 select * into old from public.sales_contact_timing_rules where project_id=pid order by version desc limit 1;
 if old.id is distinct from (p_input->>'expectedPreviousId')::uuid then raise exception 'REVISION_CONFLICT' using errcode='23505';end if;
 insert into public.sales_contact_timing_rules(project_id,owner_id,version,previous_id,request_key,request,min_wait_seconds,max_reminders,max_source_age_seconds)
 values(pid,(p_principal->>'userId')::uuid,coalesce(old.version,0)+1,old.id,(p_input->>'idempotencyKey')::uuid,p_input,(p_input->>'minWaitSeconds')::integer,(p_input->>'maxReminders')::integer,(p_input->>'maxSourceAgeSeconds')::integer) returning * into r;
 return public.sales_timing_rules_json(r);
end$$;
create function public.sales_timing_save_history(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare pid uuid;c public.sales_contacts;h public.sales_contact_history_revisions;old public.sales_contact_history_revisions;v jsonb;address text;begin
 pid:=public.sales_timing_uuid(p_input->'projectId');perform public.sales_owner(p_principal,pid);
 perform public.sales_timing_fields(p_input,array['projectId','idempotencyKey','expectedPreviousId','contactId','expectedContactVersion','data','confirmed']);
 perform public.sales_timing_uuid(p_input->'idempotencyKey');perform public.sales_timing_uuid(p_input->'contactId');
 if p_input->'expectedPreviousId'<>'null' then perform public.sales_timing_uuid(p_input->'expectedPreviousId');end if;
 if p_input->'confirmed' is distinct from 'true'::jsonb or jsonb_typeof(p_input->'expectedContactVersion')<>'number' or p_input->>'expectedContactVersion' !~ '^[1-9][0-9]{0,8}$' or octet_length(p_input::text)>65536 then raise exception 'INVALID_BODY' using errcode='22023';end if;
 perform public.sales_timing_validate_history(p_input->'data',clock_timestamp());
 perform pg_advisory_xact_lock(hashtextextended(pid::text||':sales-contact-eligibility',0));
 select * into h from public.sales_contact_history_revisions where project_id=pid and request_key=(p_input->>'idempotencyKey')::uuid;
 if found then if h.request is distinct from p_input then raise exception 'REVISION_CONFLICT' using errcode='23505';end if;return public.sales_timing_history_json(h);end if;
 select * into c from public.sales_contacts where project_id=pid and id=(p_input->>'contactId')::uuid for share;
 if not found then raise exception 'NOT_FOUND' using errcode='P0002';end if;
 if c.version<>(p_input->>'expectedContactVersion')::integer then raise exception 'REVISION_CONFLICT' using errcode='23505';end if;
 address:=lower(btrim(c.data->>'email'));
 perform pg_advisory_xact_lock(hashtextextended(pid::text||':timing-recipient:'||address,0));
 for v in select value from jsonb_array_elements(p_input->'data'->'contactVersions') loop
  if not exists(select from public.sales_contacts linked where linked.project_id=pid and linked.id=(v->>'id')::uuid and linked.version=(v->>'version')::integer and lower(btrim(linked.data->>'email'))=address) then raise exception 'REVISION_CONFLICT' using errcode='23505';end if;
 end loop;
 if not exists(select from jsonb_array_elements(p_input->'data'->'contactVersions') q where q->>'id'=c.id::text and (q->>'version')::integer=c.version) then raise exception 'INVALID_BODY' using errcode='22023';end if;
 select * into old from public.sales_contact_history_revisions where project_id=pid and recipient=address order by version desc limit 1;
 if old.id is distinct from (p_input->>'expectedPreviousId')::uuid then raise exception 'REVISION_CONFLICT' using errcode='23505';end if;
 if p_input->'data'->>'correctionOf' is not null and p_input->'data'->>'correctionOf' is distinct from old.id::text then raise exception 'INVALID_BODY' using errcode='22023';end if;
 -- A new snapshot cannot silently erase prior evidence. Corrections remain explicit.
 if old.id is not null and exists(select from jsonb_array_elements(old.data->'events') e where not exists(select from jsonb_array_elements(p_input->'data'->'events') n where n->>'id'=e->>'id' and n=e)) and p_input->'data'->>'correctionOf' is distinct from old.id::text then raise exception 'HISTORY_CORRECTION_REQUIRED' using errcode='22023';end if;
 insert into public.sales_contact_history_revisions(project_id,owner_id,recipient,version,previous_id,request_key,request,data,source_context)
 values(pid,(p_principal->>'userId')::uuid,address,coalesce(old.version,0)+1,old.id,(p_input->>'idempotencyKey')::uuid,p_input,p_input->'data',public.sales_timing_context(pid,address)) returning * into h;
 return public.sales_timing_history_json(h);
end$$;
create function public.sales_timing_evaluate(pid uuid,cid uuid,at timestamptz) returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare c public.sales_contacts;r public.sales_contact_timing_rules;h public.sales_contact_history_revisions;address text;b text[]:='{}';e jsonb;s jsonb;cv jsonb;latest timestamptz;floor_at timestamptz;through_at timestamptz;reminders integer;uncertain boolean:=false;channel text;accepted timestamptz;required_from timestamptz;begin
 select * into c from public.sales_contacts where project_id=pid and id=cid;
 if not found then raise exception 'NOT_FOUND' using errcode='P0002';end if;
 address:=lower(btrim(c.data->>'email'));
 select * into r from public.sales_contact_timing_rules where project_id=pid order by version desc limit 1;
 select * into h from public.sales_contact_history_revisions where project_id=pid and recipient=address order by version desc limit 1;
 if r.id is null then b:=array_append(b,'RULE_REVIEW_REQUIRED');end if;
 if c.data->'confirmed' is distinct from 'true'::jsonb then b:=array_append(b,'CONTACT_UNCONFIRMED');end if;
 if exists(select from public.sales_contacts x where x.project_id=pid and lower(btrim(x.data->>'email'))=address and x.data->'suppressed'='true') then b:=array_append(b,'CONTACT_SUPPRESSED');end if;
 if exists(select from public.sales_contacts x where x.project_id=pid and lower(btrim(x.data->>'email'))=address and x.data->'excluded'='true') then b:=array_append(b,'CONTACT_EXCLUDED');end if;
 if not exists(select from public.projects where id=pid and execution_paused=false) or not exists(select from public.platform_config where id=1 and automation_paused=false) then b:=array_append(b,'PROJECT_PAUSED');end if;
 if h.id is null then b:=array_append(b,'HISTORY_REVIEW_REQUIRED');
 else
  perform public.sales_timing_validate_history(h.data,at);
  if h.source_context is distinct from public.sales_timing_context(pid,address) then b:=array_append(b,'SOURCE_CHANGED');end if;
  if not exists(select from jsonb_array_elements(h.data->'contactVersions') x where x->>'id'=cid::text and (x->>'version')::integer=c.version) then b:=array_append(b,'SOURCE_CHANGED');end if;
  if exists(select from public.sales_contacts linked where linked.project_id=pid and lower(btrim(linked.data->>'email'))=address and not exists(select from jsonb_array_elements(h.data->'contactVersions') bound where bound->>'id'=linked.id::text and (bound->>'version')::integer=linked.version)) then b:=array_append(b,'SOURCE_CHANGED');end if;
  for cv in select value from jsonb_array_elements(h.data->'contactVersions') loop
   if not exists(select from public.sales_contacts linked where linked.project_id=pid and linked.id=(cv->>'id')::uuid and linked.version=(cv->>'version')::integer and lower(btrim(linked.data->>'email'))=address) then b:=array_append(b,'SOURCE_CHANGED');end if;
  end loop;
  if h.data->>'history'='unknown' or h.data->'olderHistoryAttestation'='null' then b:=array_append(b,'HISTORY_REVIEW_REQUIRED');end if;
  foreach channel in array array['strato_sent','strato_inbox','resend'] loop
   if not exists(select from jsonb_array_elements(h.data->'sources') x where x->>'channel'=channel and x->>'state'='complete') then b:=array_append(b,'SOURCE_GAP');end if;
  end loop;
  for s in select value from jsonb_array_elements(h.data->'sources') loop
   if s->>'state'<>'complete' then b:=array_append(b,'SOURCE_GAP');end if;
   if (s->>'through')::timestamptz>at then b:=array_append(b,'SOURCE_CHANGED');end if;
   through_at:=least(through_at,(s->>'through')::timestamptz);
   if r.id is not null and at-(s->>'through')::timestamptz>make_interval(secs=>r.max_source_age_seconds) then b:=array_append(b,'SOURCE_STALE');end if;
  end loop;
  select least((select min((v->>'since')::timestamptz) from jsonb_array_elements(h.data->'sources') v),(select min((v->>'occurredAt')::timestamptz) from jsonb_array_elements(h.data->'events') v)) into required_from;
  foreach channel in array array['strato_sent','strato_inbox','resend'] loop
   if not exists(select from jsonb_array_elements(h.data->'sources') coverage where coverage->>'channel'=channel and coverage->>'state'='complete' and (coverage->>'since')::timestamptz<=required_from and (coverage->>'through')::timestamptz>=through_at) then b:=array_append(b,'SOURCE_GAP');end if;
  end loop;
  reminders:=0;
  for e in select value from jsonb_array_elements(h.data->'events') loop
   if e->'reviewedDuplicateOf'<>'null' then continue;end if;
   if e->>'outcome'='delivery_unknown' then uncertain:=true;b:=array_append(b,'SEND_UNCERTAIN');end if;
   if e->>'outcome' in('bounced','unsubscribed') then b:=array_append(b,'RECIPIENT_STOPPED');end if;
   if e->>'direction'='inbound' then b:=array_append(b,'REPLY_REVIEW_REQUIRED');end if;
   if e->>'kind'='unclassified' and e->>'outcome'<>'failed_before_send' then b:=array_append(b,'EVENT_CLASSIFICATION_REQUIRED');end if;
   if e->>'direction'='outbound' and e->>'outcome'='accepted' then
    latest:=greatest(latest,(e->>'occurredAt')::timestamptz);
    if e->>'kind'='reminder' then reminders:=reminders+1;end if;
    if e->>'kind' in('initial','reminder') and e->>'invitationId' is null then b:=array_append(b,'INVITATION_UNRESOLVED');end if;
   end if;
  end loop;
  if exists(select from jsonb_array_elements(h.data->'events') ev cross join lateral jsonb_array_elements(ev->'providerRefs') p where ev->'reviewedDuplicateOf'='null' group by p->>'sourceKey',p->>'id' having count(*)>1) then b:=array_append(b,'DUPLICATE_UNRESOLVED');end if;
  if exists(select from jsonb_array_elements(h.data->'events') a join jsonb_array_elements(h.data->'events') z on a->>'id'<z->>'id' and a->>'occurredAt'=z->>'occurredAt' and a->>'direction'=z->>'direction' and a->>'outcome'=z->>'outcome' and a->>'kind'=z->>'kind' where a->'reviewedDuplicateOf'='null' and z->'reviewedDuplicateOf'='null' and a->'sourceRefs' is distinct from z->'sourceRefs') then b:=array_append(b,'DUPLICATE_UNRESOLVED');end if;
  if r.id is not null and latest is not null and reminders>=r.max_reminders then b:=array_append(b,'REMINDER_LIMIT');end if;
 end if;
 if exists(select from public.sales_send_jobs j where j.project_id=pid and lower(btrim(j.sealed_json::jsonb->>'toEmail'))=address and j.status in('queued','claimed','dispatching')) then b:=array_append(b,'SEND_PENDING');end if;
 if exists(select from public.sales_send_jobs j where j.project_id=pid and lower(btrim(j.sealed_json::jsonb->>'toEmail'))=address and j.status='delivery_unknown') then b:=array_append(b,'SEND_UNCERTAIN');uncertain:=true;end if;
 select max(accepted_at) into accepted from public.sales_send_jobs j where j.project_id=pid and lower(btrim(j.sealed_json::jsonb->>'toEmail'))=address and j.status='smtp_accepted';
 latest:=greatest(latest,accepted);
 -- Every stored matching incoming message requires review; headers cannot authorize replying.
 if exists(select from public.sales_inbox_messages m where m.project_id=pid and lower(btrim(coalesce(substring(m.header->>'from' from '<([^<>]+)>'),m.header->>'from')))=address) then b:=array_append(b,'REPLY_REVIEW_REQUIRED');end if;
 if c.data->>'history'<>'not_contacted' or h.data->>'history' is distinct from 'owner_confirmed_none' or latest is not null or exists(select from public.sales_contacts x where x.project_id=pid and lower(btrim(x.data->>'email'))=address and x.data->>'history'='contacted') then b:=array_append(b,'NOT_INITIAL_CONTACT');end if;
 if uncertain or 'DUPLICATE_UNRESOLVED'=any(b) or 'EVENT_CLASSIFICATION_REQUIRED'=any(b) or 'SOURCE_GAP'=any(b) or 'HISTORY_REVIEW_REQUIRED'=any(b) then latest:=null;reminders:=null;end if;
 if latest is not null and r.id is not null then floor_at:=latest+make_interval(secs=>r.min_wait_seconds);if at<floor_at then b:=array_append(b,'WAIT_INTERVAL');end if;end if;
 select coalesce(array_agg(distinct value order by value),'{}') into b from unnest(b) value;
 return jsonb_build_object('contactId',cid,'recipient',address,'contactVersion',c.version,'historyRevisionId',h.id,'ruleRevisionId',r.id,'latestObservedOutboundAt',latest,'reminderCount',reminders,'intervalFloorAt',floor_at,'sourceThrough',through_at,'blockers',to_jsonb(b),'initialPreparationAllowed',cardinality(b)=0);
end$$;
create function public.sales_timing_read(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql stable security invoker set search_path='' as $$
declare pid uuid;at timestamptz:=clock_timestamp();rows jsonb;r public.sales_contact_timing_rules;ids jsonb:=p_input->'contactIds';n integer;slug text;begin
 pid:=public.sales_timing_uuid(p_input->'projectId');perform public.sales_owner(p_principal,pid);
 if jsonb_typeof(p_input) is distinct from 'object' or exists(select from jsonb_object_keys(p_input) k where k not in('projectId','contactIds')) then raise exception 'INVALID_BODY' using errcode='22023';end if;
 if ids is not null then
  if jsonb_typeof(ids)<>'array' or jsonb_array_length(ids) not between 1 and 200 then raise exception 'INVALID_BODY' using errcode='22023';end if;
  perform public.sales_timing_uuid(value) from jsonb_array_elements(ids);
  if (select count(*)<>count(distinct value) from jsonb_array_elements(ids)) then raise exception 'INVALID_BODY' using errcode='22023';end if;
 end if;
 select count(*) into n from public.sales_contacts where project_id=pid and (ids is null or ids @> jsonb_build_array(id));
 if n>200 then raise exception 'TIMING_SELECTION_TOO_LARGE' using errcode='22023';end if;
 if ids is not null and n<>jsonb_array_length(ids) then raise exception 'NOT_FOUND' using errcode='P0002';end if;
 select jsonb_agg(public.sales_timing_evaluate(pid,id,at) order by data->>'companyName',id) into rows from public.sales_contacts where project_id=pid and (ids is null or ids @> jsonb_build_array(id));
 select * into r from public.sales_contact_timing_rules where project_id=pid order by version desc limit 1;
 select p.slug into slug from public.projects p where p.id=pid;
 return jsonb_build_object('projectId',pid,'evaluatedAt',at,'contacts',coalesce(rows,'[]'),'historyRevisions',coalesce((select jsonb_agg(public.sales_timing_history_json(h)) from public.sales_contact_history_revisions h where h.project_id=pid and h.id in(select (value->>'historyRevisionId')::uuid from jsonb_array_elements(rows))),'[]'),'rules',case when r.id is null then null else public.sales_timing_rules_json(r) end,'customerSendingEnabled',false,'workspaceUrl','/projects/'||slug||'/sales#contact-timing');
end$$;
-- Explicitly close PUBLIC's default function execution. Service calls still validate owner.
do $$declare f regprocedure;begin
 for f in select p.oid::regprocedure from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'sales_timing_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f);
  execute format('grant execute on function %s to service_role',f);
 end loop;
end$$;


create function public.sales_timing_assert_snapshot(j public.sales_jobs) returns void language plpgsql security invoker set search_path='' as $$
declare old jsonb;current_timing jsonb;begin
 perform pg_advisory_xact_lock(hashtextextended(j.project_id::text||':sales-contact-eligibility',0));
 lock table public.sales_inbox_messages,public.sales_send_jobs in share mode;
 if jsonb_typeof(j.snapshot->'timing'->'contacts') is distinct from 'array' or jsonb_array_length(j.snapshot->'timing'->'contacts')<>jsonb_array_length(j.snapshot->'contacts') then raise exception 'CONTACT_TIMING_CHANGED' using errcode='40001';end if;
 for old in select value from jsonb_array_elements(j.snapshot->'timing'->'contacts') loop
  current_timing:=public.sales_timing_evaluate(j.project_id,(old->>'contactId')::uuid,clock_timestamp());
  if current_timing->>'initialPreparationAllowed' is distinct from 'true' or current_timing->'historyRevisionId' is distinct from old->'historyRevisionId' or current_timing->'ruleRevisionId' is distinct from old->'ruleRevisionId' or current_timing->'contactVersion' is distinct from old->'contactVersion' then raise exception 'CONTACT_TIMING_CHANGED' using errcode='40001';end if;
 end loop;
end$$;
revoke all on function public.sales_timing_assert_snapshot(public.sales_jobs) from public,anon,authenticated;
grant execute on function public.sales_timing_assert_snapshot(public.sales_jobs) to service_role;

create or replace function public.sales_prepare_job(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare pid uuid:=(p_input->>'projectId')::uuid;j public.sales_jobs;o jsonb;contacts jsonb;expected integer;timing jsonb;
begin
 perform public.sales_owner(p_principal,pid);
 if not exists(select 1 from public.conversations where id=(p_input->>'conversationId')::uuid and user_id=(p_principal->>'userId')::uuid and project_id=pid) then raise exception 'NOT_FOUND' using errcode='P0002';end if;
 perform pg_advisory_xact_lock(hashtextextended(pid::text||':'||(p_input->>'idempotencyKey'),0));
 select * into j from public.sales_jobs where project_id=pid and request_key=p_input->>'idempotencyKey';
 if found then if j.request<>p_input then raise exception 'REVISION_CONFLICT' using errcode='23505';end if;return public.sales_job_json(j);end if;
 perform public.sales_stop(pid);
 perform pg_advisory_xact_lock(hashtextextended(pid::text||':sales-contact-eligibility',0));
 expected:=jsonb_array_length(p_input->'contactIds');if expected not between 1 and 5 then raise exception 'INVALID_BODY' using errcode='22023';end if;
 select jsonb_agg(c.data order by c.id) into contacts from public.sales_contacts c where c.project_id=pid and (p_input->'contactIds') @> jsonb_build_array(c.id::text) and c.data->>'history'='not_contacted' and (c.data->>'confirmed')::boolean is true and (c.data->>'excluded')::boolean is false and (c.data->>'suppressed')::boolean is false;
 if coalesce(jsonb_array_length(contacts),0)<>expected then raise exception 'CONTACT_REVIEW_REQUIRED' using errcode='55000';end if;
 if exists(select from public.sales_contacts c where c.project_id=pid and (c.data->>'history'='contacted' or (c.data->>'suppressed')::boolean is true) and exists(select from jsonb_array_elements(contacts) selected where lower(selected->>'email')=lower(c.data->>'email'))) then raise exception 'MAILBOX_REVIEW_REQUIRED' using errcode='55000';end if;
 if exists(select from public.sales_jobs previous cross join lateral jsonb_array_elements(previous.snapshot->'contacts') old_contact where previous.project_id=pid and previous.status not in('cancelled','failed') and exists(select from jsonb_array_elements(contacts) selected where lower(selected->>'email')=lower(old_contact->>'email'))) then raise exception 'INITIAL_JOB_ALREADY_EXISTS' using errcode='55000';end if;
 select data into o from public.sales_offer_revisions where project_id=pid and id=(p_input->>'offerRevisionId')::uuid;
 if not found then raise exception 'NOT_FOUND' using errcode='P0002';end if;
 if exists(select from jsonb_array_elements(contacts) c where c->>'pilotMonths' is distinct from o->>'freeMonths') then raise exception 'PILOT_TIER_MISMATCH' using errcode='55000';end if;
 lock table public.sales_inbox_messages,public.sales_send_jobs in share mode;
 timing:=public.sales_timing_read(p_principal,jsonb_build_object('projectId',pid,'contactIds',p_input->'contactIds'));
 if exists(select from jsonb_array_elements(timing->'contacts') x where x->>'initialPreparationAllowed' is distinct from 'true') then raise exception 'CONTACT_TIMING_REVIEW_REQUIRED' using errcode='55000';end if;
 insert into public.sales_jobs(project_id,owner_id,request_key,request,snapshot) values(pid,(p_principal->>'userId')::uuid,p_input->>'idempotencyKey',p_input,jsonb_build_object('contacts',contacts,'offer',o,'timing',timing)) returning * into j;
 return public.sales_job_json(j);
end $$;
create or replace function public.sales_assert_contacts(j public.sales_jobs) returns void language plpgsql security invoker set search_path='' as $$
begin
 perform public.sales_timing_assert_snapshot(j);
 perform pg_advisory_xact_lock(hashtextextended(j.project_id::text||':sales-contact-eligibility',0));
 if exists(select from jsonb_array_elements(j.snapshot->'contacts') old_contact where not exists(select from public.sales_contacts c where c.project_id=j.project_id and c.id=(old_contact->>'id')::uuid and c.version=(old_contact->>'version')::integer and c.data->>'history'='not_contacted' and (c.data->>'confirmed')::boolean is true and (c.data->>'excluded')::boolean is false and (c.data->>'suppressed')::boolean is false)) then raise exception 'CONTACT_CHANGED' using errcode='40001';end if;
 if exists(select from public.sales_contacts c where c.project_id=j.project_id and (c.data->>'history'='contacted' or (c.data->>'suppressed')::boolean is true) and exists(select from jsonb_array_elements(j.snapshot->'contacts') old_contact where lower(old_contact->>'email')=lower(c.data->>'email'))) then raise exception 'MAILBOX_CHANGED' using errcode='40001';end if;
end $$;
create or replace function public.sales_read_workspace(p_principal jsonb,p_input jsonb) returns jsonb language plpgsql security invoker set search_path='' as $$
declare pid uuid:=(p_input->>'projectId')::uuid;slug text;
begin perform public.sales_owner(p_principal,pid);perform public.sales_reconcile_expired(pid);select p.slug into slug from public.projects p where id=pid;
 return jsonb_build_object('projectId',pid,'state','ok','sendingEnabled',false,'workspaceUrl','/projects/'||slug||'/sales',
 'timing',public.sales_timing_read(p_principal,jsonb_build_object('projectId',pid)),
 'workerState',case when exists(select from public.sales_worker_registrations where project_id=pid and revoked_at is null and expires_at>now() and last_seen_at>now()-interval '90 seconds') then 'connected' else 'not_connected' end,
 'evidence',coalesce((select jsonb_agg(jsonb_build_object('id',e.id,'contactId',e.contact_id,'source',e.data,'question',e.question,'provenance',e.provenance)) from public.sales_evidence e where e.project_id=pid),'[]'),
 'workers',coalesce((select jsonb_agg(jsonb_build_object('id',id,'expiresAt',expires_at,'lastSeenAt',last_seen_at,'revoked',revoked_at is not null)) from public.sales_worker_registrations where project_id=pid),'[]'),
 'contacts',coalesce((select jsonb_agg(data order by created_at) from public.sales_contacts where project_id=pid),'[]'),
 'offers',coalesce((select jsonb_agg(data order by created_at desc) from public.sales_offer_revisions where project_id=pid),'[]'),
 'jobs',coalesce((select jsonb_agg(public.sales_job_json(j) order by created_at desc) from (select * from public.sales_jobs where project_id=pid order by created_at desc limit 20) j),'[]'),
 'drafts',coalesce((select jsonb_agg(d.data||jsonb_build_object('id',d.id,'projectId',pid,'jobId',d.job_id,'sha256',d.sha256,'approvalId',d.approval_id,'runId',d.run_id,'status',coalesce(a.status,'needs_input'),'current',d.is_current,'createdAt',d.created_at) order by d.created_at desc) from public.sales_draft_revisions d left join public.approvals a on a.id=d.approval_id where d.project_id=pid and d.is_current),'[]'));
end $$;

-- Recipient-free copy revisions only. No transport, recipient, contact or scheduler authority.
create table public.sales_email_copy_revisions (
 id uuid primary key default gen_random_uuid(),
 project_id uuid not null references public.projects(id) on delete cascade,
 owner_id uuid not null references auth.users(id),
 template_key text not null check (template_key ~ '^[a-z][a-z0-9-]{0,79}$'),
 version integer not null check (version>0),
 previous_id uuid references public.sales_email_copy_revisions(id),
 request_key uuid not null,
 request jsonb not null,
 data jsonb not null,
 created_at timestamptz not null default clock_timestamp(),
 unique(project_id,template_key,version),
 unique(project_id,request_key),
 check ((version=1 and previous_id is null) or (version>1 and previous_id is not null)),
 check (data @> '{"status":"draft","recipient":null,"scheduledAt":null,"ownerTextReviewed":false}'::jsonb)
);
alter table public.sales_email_copy_revisions enable row level security;
revoke all on public.sales_email_copy_revisions from public,anon,authenticated,service_role;
grant select,insert on public.sales_email_copy_revisions to service_role;

create or replace function public.sales_email_copy_json(r public.sales_email_copy_revisions)
returns jsonb language sql stable security invoker set search_path='' as $fn$
 select r.data||jsonb_build_object('id',r.id,'projectId',r.project_id,'templateKey',r.template_key,'version',r.version,'previousId',r.previous_id,'createdAt',r.created_at,'createdBy',r.owner_id);
$fn$;

create or replace function public.sales_email_copy_read(p_principal jsonb,p_input jsonb)
returns jsonb language plpgsql stable security invoker set search_path='' as $fn$
declare pid uuid;
begin
 pid:=public.sales_timing_uuid(p_input->'projectId');
 perform public.sales_owner(p_principal,pid);
 perform public.sales_timing_fields(p_input,array['projectId']);
 return coalesce((select jsonb_agg(public.sales_email_copy_json(r) order by r.template_key,r.version desc) from public.sales_email_copy_revisions r where project_id=pid),'[]'::jsonb);
end $fn$;

create or replace function public.sales_email_copy_save(p_principal jsonb,p_input jsonb)
returns jsonb language plpgsql security invoker set search_path='' as $fn$
declare pid uuid;k text;r public.sales_email_copy_revisions;old public.sales_email_copy_revisions;seed jsonb;offer jsonb;d jsonb;subject text;body text;
begin
 pid:=public.sales_timing_uuid(p_input->'projectId');
 perform public.sales_owner(p_principal,pid);
 perform public.sales_timing_fields(p_input,array['projectId','templateKey','expectedPreviousId','idempotencyKey','subject','body']);
 perform public.sales_timing_uuid(p_input->'idempotencyKey');
 if p_input->'expectedPreviousId'<>'null' then perform public.sales_timing_uuid(p_input->'expectedPreviousId');end if;
 k:=p_input->>'templateKey';subject:=p_input->>'subject';body:=p_input->>'body';
 if jsonb_typeof(p_input->'templateKey') is distinct from 'string' or k !~ '^[a-z][a-z0-9-]{0,79}$' or
 jsonb_typeof(p_input->'subject') is distinct from 'string' or length(btrim(subject))=0 or length(subject)>90 or subject ~ '[[:cntrl:]]' or
 jsonb_typeof(p_input->'body') is distinct from 'string' or length(btrim(body,E' \t\r\n'))=0 or length(body)>2000 or translate(body,chr(9)||chr(10)||chr(13),'') ~ '[[:cntrl:]]'
 then raise exception 'INVALID_BODY' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(pid::text||':sales-email-copy',0));
 select * into r from public.sales_email_copy_revisions where project_id=pid and request_key=(p_input->>'idempotencyKey')::uuid;
 if found then
  if r.request is distinct from p_input then raise exception 'REVISION_CONFLICT' using errcode='23505';end if;
  return public.sales_email_copy_json(r);
 end if;
 select * into old from public.sales_email_copy_revisions where project_id=pid and template_key=k order by version desc limit 1;
 if old.id is distinct from (p_input->>'expectedPreviousId')::uuid then raise exception 'REVISION_CONFLICT' using errcode='23505';end if;
 if old.id is null then
  select x into seed from public.memories m cross join lateral jsonb_array_elements(m.value::jsonb->'templates') x
   where m.project_id=pid and m.key='handlarborsen.sales.email_copy_proposals' and x->>'id'=k;
  if seed is null then raise exception 'NOT_FOUND' using errcode='P0002';end if;
  if seed->>'subject' is distinct from subject or seed->>'body' is distinct from body or jsonb_typeof(seed->'kind') is distinct from 'string' or seed->>'kind' not in ('initial','reminder') or
   jsonb_typeof(seed->'senderName') is distinct from 'string' or jsonb_typeof(seed->'usage') is distinct from 'string' or
   length(btrim(seed->>'senderName')) not between 1 and 100 or seed->>'senderName' ~ '[[:cntrl:]]' or
   length(btrim(seed->>'usage')) not between 1 and 1000 then raise exception 'INVALID_BODY' using errcode='22023';end if;
  select o.data into offer from public.sales_offer_revisions o where o.project_id=pid and o.id=public.sales_timing_uuid(seed->'offerRevisionId');
  if offer is null or offer->'confirmed' is distinct from 'true'::jsonb or offer->'freeMonths' is distinct from seed->'pilotMonths' or offer->>'senderEmail' is distinct from seed->>'senderEmail' then raise exception 'INVALID_BODY' using errcode='22023';end if;
  if jsonb_typeof(offer->'freeMonths') is distinct from 'number' or jsonb_typeof(offer->'senderEmail') is distinct from 'string' or
   jsonb_typeof(offer->'offerText') is distinct from 'string' or jsonb_typeof(offer->'productFacts') is distinct from 'array'
   then raise exception 'INVALID_BODY' using errcode='22023';end if;
  if offer->'freeMonths' not in ('2'::jsonb,'6'::jsonb,'12'::jsonb) or
   length(offer->>'senderEmail') not between 3 and 254 or offer->>'senderEmail' !~ '^[^[:space:]@<>]+@[^[:space:]@<>]+[.][^[:space:]@<>]+$' or offer->>'senderEmail' ~ '[[:cntrl:]]' or
   length(btrim(offer->>'offerText',E' \t\r\n')) not between 1 and 2000 or jsonb_array_length(offer->'productFacts') not between 1 and 10
   then raise exception 'INVALID_BODY' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(offer->'productFacts') fact where jsonb_typeof(fact) is distinct from 'string' or length(btrim(fact#>>'{}',E' \t\r\n')) not between 1 and 1000)
   then raise exception 'INVALID_BODY' using errcode='22023';end if;
  d:=jsonb_build_object('kind',seed->'kind','offerRevisionId',seed->'offerRevisionId','pilotMonths',seed->'pilotMonths',
   'offerText',offer->'offerText','productFacts',offer->'productFacts','senderName',seed->'senderName','senderEmail',offer->'senderEmail','usage',seed->'usage');
 else
  if old.data->>'subject'=subject and old.data->>'body'=body then raise exception 'INVALID_BODY' using errcode='22023';end if;
  d:=old.data;
 end if;
 d:=d||jsonb_build_object('subject',subject,'body',body,'status','draft','recipient',null,'scheduledAt',null,'ownerTextReviewed',false);
 insert into public.sales_email_copy_revisions(project_id,owner_id,template_key,version,previous_id,request_key,request,data)
