   or (draft->'time'->>'kind'='timed'
    and (draft->'time'->>'startUtc')::timestamptz < (last_date::timestamp at time zone 'Europe/Stockholm')
    and coalesce((draft->'time'->>'endUtc')::timestamptz,(draft->'time'->>'startUtc')::timestamptz) >= (first_date::timestamp at time zone 'Europe/Stockholm')
    and ((draft->'time'->>'endUtc') is null or (draft->'time'->>'endUtc')::timestamptz > (first_date::timestamp at time zone 'Europe/Stockholm')))
  ) order by created_at,id limit 501
 ) e;
 return jsonb_build_object('events',(select coalesce(jsonb_agg(value),'[]') from jsonb_array_elements(items) with ordinality x(value,n) where n<=500),'truncated',jsonb_array_length(items)>500);
exception when invalid_text_representation or invalid_datetime_format or datetime_field_overflow then return jsonb_build_object('ok',false,'code','INVALID_INPUT');
end $fn$;

-- Project-owned provider OAuth credentials. No social-token changes.
create table public.media_provider_connections (
 project_id uuid primary key references public.projects(id) on delete cascade,
 provider text not null default 'higgsfield' check (provider='higgsfield'),
 connection_version bigint not null default 0 check(connection_version>=0),
 issuer text not null default 'https://clerk.higgsfield.ai' check(issuer='https://clerk.higgsfield.ai'),
 encrypted_payload jsonb,
 subject text,
 identity_verified boolean not null default false,
 status text not null default 'disconnected' check(status in ('disconnected','connected','reconnect_required')),
 refresh_lease uuid,
 refresh_lease_until timestamptz,
 updated_at timestamptz not null default clock_timestamp(),
 check(encrypted_payload is null or (jsonb_typeof(encrypted_payload)='object' and encrypted_payload->>'v'='1')),
 check(status<>'connected' or encrypted_payload is not null),
 check(not identity_verified or subject is not null)
);
create table public.media_provider_oauth_states (
 state_hash text primary key check(state_hash ~ '^[a-f0-9]{64}$'),
 project_id uuid not null references public.media_provider_connections(project_id) on delete cascade,
 actor_id uuid not null references auth.users(id) on delete cascade,
 connection_version bigint not null check(connection_version>=0),
 encrypted_payload jsonb not null check(jsonb_typeof(encrypted_payload)='object' and encrypted_payload->>'v'='1'),
 expires_at timestamptz not null default (clock_timestamp()+interval '10 minutes'),
 consumed_at timestamptz
);
create index media_provider_oauth_states_project_idx on public.media_provider_oauth_states(project_id);
alter table public.media_provider_connections enable row level security;
alter table public.media_provider_oauth_states enable row level security;
-- Supabase grants service_role ALL on new public tables by default. Revoke
-- those inherited DELETE/TRUNCATE/etc rights before narrowly granting only
-- the operations required by these SECURITY INVOKER RPCs.
revoke all on public.media_provider_connections,public.media_provider_oauth_states from public,anon,authenticated,service_role;
grant select,insert,update on public.media_provider_connections,public.media_provider_oauth_states to service_role;

create function public.higgsfield_connection_read(p_project uuid) returns jsonb
language sql security invoker set search_path='' as $$
 select to_jsonb(c) from public.media_provider_connections c where c.project_id=p_project
$$;
create function public.higgsfield_oauth_create(p_project uuid,p_actor uuid,p_state text,p_version bigint,p_payload jsonb) returns boolean
language plpgsql security invoker set search_path='' as $$
declare current_version bigint;
begin
 insert into public.media_provider_connections(project_id) values(p_project) on conflict do nothing;
 select connection_version into current_version from public.media_provider_connections where project_id=p_project for update;
 if current_version is distinct from p_version then return false; end if;
 insert into public.media_provider_oauth_states(state_hash,project_id,actor_id,connection_version,encrypted_payload)
 values(p_state,p_project,p_actor,p_version,p_payload);
 return true;
end $$;
create function public.higgsfield_oauth_peek(p_state text,p_actor uuid) returns jsonb
language sql security invoker set search_path='' as $$
 select jsonb_build_object('project_id',s.project_id) from public.media_provider_oauth_states s
 join public.media_provider_connections c on c.project_id=s.project_id and c.connection_version=s.connection_version
 where s.state_hash=p_state and s.actor_id=p_actor and s.consumed_at is null and s.expires_at>clock_timestamp()
$$;
revoke all on function public.higgsfield_oauth_peek(text,uuid) from public,anon,authenticated;
grant execute on function public.higgsfield_oauth_peek(text,uuid) to service_role;
create function public.higgsfield_oauth_consume(p_state text,p_actor uuid) returns jsonb
language plpgsql security invoker set search_path='' as $$
declare s public.media_provider_oauth_states; c public.media_provider_connections;
begin
 -- Same lock order as disconnect: connection first, then attempt.
 select * into s from public.media_provider_oauth_states where state_hash=p_state and actor_id=p_actor;
 if not found then return null; end if;
 select * into c from public.media_provider_connections where project_id=s.project_id for update;
 update public.media_provider_oauth_states set consumed_at=clock_timestamp()
 where state_hash=p_state and actor_id=p_actor and consumed_at is null
 and expires_at>clock_timestamp() and connection_version=c.connection_version
 returning * into s;
 if not found then return null; end if;
 return to_jsonb(s);
end $$;
create function public.higgsfield_connection_save(p_project uuid,p_version bigint,p_payload jsonb,p_subject text,p_verified boolean,p_lease uuid default null) returns boolean
language plpgsql security invoker set search_path='' as $$
begin
 update public.media_provider_connections set
 encrypted_payload=p_payload,subject=p_subject,identity_verified=p_verified,status='connected',
 connection_version=connection_version+1,refresh_lease=null,refresh_lease_until=null,updated_at=clock_timestamp()
 where project_id=p_project and connection_version=p_version
 and ((p_lease is null and (refresh_lease is null or refresh_lease_until<=clock_timestamp())) or
      (p_lease is not null and refresh_lease=p_lease and refresh_lease_until>clock_timestamp()));
 return found;
end $$;
create function public.higgsfield_refresh_acquire(p_project uuid,p_version bigint) returns uuid
language plpgsql security invoker set search_path='' as $$
declare lease uuid:=gen_random_uuid();
begin
 update public.media_provider_connections set refresh_lease=lease,refresh_lease_until=clock_timestamp()+interval '30 seconds'
 where project_id=p_project and connection_version=p_version and status='connected'
 and (refresh_lease is null or refresh_lease_until<=clock_timestamp());
 if not found then return null; end if;
 return lease;
end $$;
create function public.higgsfield_refresh_release(p_project uuid,p_lease uuid) returns void
language sql security invoker set search_path='' as $$
 update public.media_provider_connections set refresh_lease=null,refresh_lease_until=null
 where project_id=p_project and refresh_lease=p_lease
$$;
create function public.higgsfield_reconnect_required(p_project uuid,p_version bigint) returns void
language sql security invoker set search_path='' as $$
 update public.media_provider_connections set status='reconnect_required',encrypted_payload=null,
 identity_verified=false,connection_version=connection_version+1,refresh_lease=null,refresh_lease_until=null,updated_at=clock_timestamp()
 where project_id=p_project and connection_version=p_version
$$;
create function public.higgsfield_connection_disconnect(p_project uuid) returns void
language plpgsql security invoker set search_path='' as $$
begin
 insert into public.media_provider_connections(project_id) values(p_project) on conflict do nothing;
 perform 1 from public.media_provider_connections where project_id=p_project for update;
 update public.media_provider_connections set encrypted_payload=null,subject=null,identity_verified=false,
 status='disconnected',connection_version=connection_version+1,refresh_lease=null,refresh_lease_until=null,updated_at=clock_timestamp()
 where project_id=p_project;
 update public.media_provider_oauth_states set consumed_at=coalesce(consumed_at,clock_timestamp()) where project_id=p_project;
end $$;

revoke all on function public.higgsfield_connection_read(uuid),
 public.higgsfield_oauth_create(uuid,uuid,text,bigint,jsonb),
 public.higgsfield_oauth_consume(text,uuid),
 public.higgsfield_connection_save(uuid,bigint,jsonb,text,boolean,uuid),
 public.higgsfield_refresh_acquire(uuid,bigint),
 public.higgsfield_refresh_release(uuid,uuid),
 public.higgsfield_reconnect_required(uuid,bigint),
 public.higgsfield_connection_disconnect(uuid) from public,anon,authenticated;
grant execute on function public.higgsfield_connection_read(uuid),
 public.higgsfield_oauth_create(uuid,uuid,text,bigint,jsonb),
 public.higgsfield_oauth_consume(text,uuid),
 public.higgsfield_connection_save(uuid,bigint,jsonb,text,boolean,uuid),
 public.higgsfield_refresh_acquire(uuid,bigint),
 public.higgsfield_refresh_release(uuid,uuid),
 public.higgsfield_reconnect_required(uuid,bigint),
 public.higgsfield_connection_disconnect(uuid) to service_role;

-- Atlas reserve allowance, owner approved: SEK 10/day and SEK 100/month.
-- Database-reserved ceilings, shared across the three allowlisted text tasks.
-- Conservative append-only reservations: never refund an ambiguous provider request.
-- No provider calls / workflow changes; disabled in application until activated.
CREATE TABLE IF NOT EXISTS public.atlas_fallback_reservations (
  request_id uuid PRIMARY KEY,
  project_id uuid NOT NULL REFERENCES public.projects(id),
  task_kind text NOT NULL CHECK(task_kind IN ('news','briefing','dream','media')),
  ceiling_sek numeric(12,4) NOT NULL CHECK(ceiling_sek > 0 AND ceiling_sek <= 10),
  reserved_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS atlas_fallback_reservations_time_idx
  ON public.atlas_fallback_reservations(reserved_at);
ALTER TABLE public.atlas_fallback_reservations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.atlas_fallback_reservations FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT ON public.atlas_fallback_reservations TO service_role;

-- Invoker + service_role-only RPC. It runs under one global xact advisory lock
-- so concurrent projects and function instances cannot reserve past the caps.
-- Europe/Stockholm calendar day/month, including DST changes.
CREATE OR REPLACE FUNCTION public.atlas_fallback_reserve(
  p_request_id uuid, p_project_id uuid, p_task_kind text, p_ceiling_sek numeric
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
  v_now timestamptz := clock_timestamp();
  v_day_start timestamptz;
  v_month_start timestamptz;
  v_amount numeric(12,4);
  v_day_used numeric(12,4);
  v_month_used numeric(12,4);
  v_slug text;
BEGIN
  IF p_request_id IS NULL OR p_project_id IS NULL OR p_task_kind IS NULL
    OR p_task_kind NOT IN ('news','briefing','dream','media')
    OR p_ceiling_sek IS NULL OR p_ceiling_sek <= 0 OR p_ceiling_sek > 10
    OR p_ceiling_sek::text IN ('NaN','Infinity','-Infinity') THEN
    RETURN pg_catalog.jsonb_build_object('allowed',false,'reason','invalid_request');
  END IF;
  v_amount := pg_catalog.ceil(p_ceiling_sek * 100)::numeric / 100;
  IF v_amount < 0.01 OR v_amount > 10 THEN
    RETURN pg_catalog.jsonb_build_object('allowed',false,'reason','invalid_amount');
  END IF;

  -- The caller must represent a real project. The Prompt-only tasks cannot
  -- spend on arbitrary tenants even if an internal code path is misrouted.
  SELECT p.slug INTO v_slug FROM public.projects AS p WHERE p.id=p_project_id;
  IF v_slug IS NULL OR (p_task_kind IN ('news','briefing','media') AND v_slug <> 'ai-media-automation') THEN
    RETURN pg_catalog.jsonb_build_object('allowed',false,'reason','wrong_project');
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(172961, 10010);
  -- Existing idempotency request never authorizes another dispatch.
  IF EXISTS(SELECT 1 FROM public.atlas_fallback_reservations WHERE request_id=p_request_id) THEN
    RETURN pg_catalog.jsonb_build_object('allowed',false,'reason','replay');
  END IF;

  v_day_start := pg_catalog.date_trunc('day', v_now AT TIME ZONE 'Europe/Stockholm')
                    AT TIME ZONE 'Europe/Stockholm';
  v_month_start := pg_catalog.date_trunc('month', v_now AT TIME ZONE 'Europe/Stockholm')
                      AT TIME ZONE 'Europe/Stockholm';
  SELECT COALESCE(SUM(ceiling_sek),0) INTO v_day_used
  FROM public.atlas_fallback_reservations WHERE reserved_at >= v_day_start;
  SELECT COALESCE(SUM(ceiling_sek),0) INTO v_month_used
  FROM public.atlas_fallback_reservations WHERE reserved_at >= v_month_start;
  IF v_day_used + v_amount > 10 OR v_month_used + v_amount > 100 THEN
    RETURN pg_catalog.jsonb_build_object('allowed',false,
      'reason',CASE WHEN v_day_used + v_amount > 10 THEN 'daily_limit' ELSE 'monthly_limit' END);
  END IF;

  INSERT INTO public.atlas_fallback_reservations(
    request_id, project_id, task_kind, ceiling_sek, reserved_at
  ) VALUES(p_request_id, p_project_id, p_task_kind, v_amount, v_now);

  RETURN pg_catalog.jsonb_build_object('allowed',true,'reason','reserved');
END;
$function$;
REVOKE ALL ON FUNCTION public.atlas_fallback_reserve(uuid,uuid,text,numeric)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.atlas_fallback_reserve(uuid,uuid,text,numeric)
  TO service_role;

-- Lock-time budget boundary: when a concurrent reservation waits across
-- Stockholm midnight, use the instant AFTER acquiring the transaction lock.
-- No data migration or reduction of permissions.
CREATE OR REPLACE FUNCTION public.atlas_fallback_reserve(
  p_request_id uuid, p_project_id uuid, p_task_kind text, p_ceiling_sek numeric
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = ''
AS $function$
DECLARE
  v_now timestamptz;
  v_day_start timestamptz;
  v_month_start timestamptz;
  v_amount numeric(12,4);
  v_day_used numeric(12,4);
  v_month_used numeric(12,4);
  v_slug text;
BEGIN
  IF p_request_id IS NULL OR p_project_id IS NULL OR p_task_kind IS NULL
    OR p_task_kind NOT IN ('news','briefing','dream','media')
    OR p_ceiling_sek IS NULL OR p_ceiling_sek <= 0 OR p_ceiling_sek > 10
    OR p_ceiling_sek::text IN ('NaN','Infinity','-Infinity') THEN
    RETURN pg_catalog.jsonb_build_object('allowed',false,'reason','invalid_request');
  END IF;
  v_amount := pg_catalog.ceil(p_ceiling_sek * 100)::numeric / 100;
  IF v_amount < 0.01 OR v_amount > 10 THEN
    RETURN pg_catalog.jsonb_build_object('allowed',false,'reason','invalid_amount');
  END IF;

  -- The caller must represent a real project. The Prompt-only tasks cannot
  -- spend on arbitrary tenants even if an internal code path is misrouted.
  SELECT p.slug INTO v_slug FROM public.projects AS p WHERE p.id=p_project_id;
  IF v_slug IS NULL OR (p_task_kind IN ('news','briefing','media') AND v_slug <> 'ai-media-automation') THEN
    RETURN pg_catalog.jsonb_build_object('allowed',false,'reason','wrong_project');
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(172961, 10010);
  -- Establish the billable calendar instant AFTER acquiring the global lock.
  -- Otherwise a waiter straddling midnight could consume the previous day.
  v_now := clock_timestamp();
  -- Existing idempotency request never authorizes another dispatch.
  IF EXISTS(SELECT 1 FROM public.atlas_fallback_reservations WHERE request_id=p_request_id) THEN
    RETURN pg_catalog.jsonb_build_object('allowed',false,'reason','replay');
  END IF;

  v_day_start := pg_catalog.date_trunc('day', v_now AT TIME ZONE 'Europe/Stockholm')
                    AT TIME ZONE 'Europe/Stockholm';
  v_month_start := pg_catalog.date_trunc('month', v_now AT TIME ZONE 'Europe/Stockholm')
                      AT TIME ZONE 'Europe/Stockholm';
  SELECT COALESCE(SUM(ceiling_sek),0) INTO v_day_used
  FROM public.atlas_fallback_reservations WHERE reserved_at >= v_day_start;
  SELECT COALESCE(SUM(ceiling_sek),0) INTO v_month_used
  FROM public.atlas_fallback_reservations WHERE reserved_at >= v_month_start;
  IF v_day_used + v_amount > 10 OR v_month_used + v_amount > 100 THEN
    RETURN pg_catalog.jsonb_build_object('allowed',false,
      'reason',CASE WHEN v_day_used + v_amount > 10 THEN 'daily_limit' ELSE 'monthly_limit' END);
  END IF;

  INSERT INTO public.atlas_fallback_reservations(
    request_id, project_id, task_kind, ceiling_sek, reserved_at
  ) VALUES(p_request_id, p_project_id, p_task_kind, v_amount, v_now);

  RETURN pg_catalog.jsonb_build_object('allowed',true,'reason','reserved');
END;
$function$;
REVOKE ALL ON FUNCTION public.atlas_fallback_reserve(uuid,uuid,text,numeric)
  FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.atlas_fallback_reserve(uuid,uuid,text,numeric)
  TO service_role;
